  FT["PH-H9522"] = {"id":"PH-H9522","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11077_2018.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将阿克兰省重新划分为两个立法选区的法案","en":"An Act Reapportioning the Province of Aklan Into Two (2) Legislative Districts","orig":"An Act Reapportioning the Province of Aklan Into Two (2) Legislative Districts"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11077","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-24","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11077_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9522-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Legislative Districts. - The Province of Aklan is hereby reapportioned into two (2) legislative districts to commence in the next national and local elections after the effectivity of this Act. Each district shall be composed of the following:\n(a) FIRST LEGISLATIVE DISTRICT:\n(1) Altavas\n(2) Balete\n(3) Banga\n(4) Batan\n(5) Kalibo\n(6) New Washington\n(7) Libacao\n(8) Madalag\n(b) SECOND LEGISLATIVE DISTRICT:\n(1) Buruanga\n(2) Ibajay\n(3) Lezo\n(4) Makato\n(5) Malay\n(6) Malinao\n(7) Nabas\n(8) Numancia\n(9) Tangalan"}},{"id":"PH-H9522-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Incumbent Representatives. – The incumbent Representative of the Lone Legislative District of the Province of Aklan shall continue to represent the legislative district until the new Representatives have been duly elected and qualified."}},{"id":"PH-H9522-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementing Rules and Regulations. – The Commission on Elections shall issue the necessary rules and regulations to implement this Act within thirty (30) days upon the effectivity of this Act."}},{"id":"PH-H9522-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause. – All laws, rules and regulations which are inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9522-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reapportioning the Province of Aklan Into Two (2) Legislative Districts","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9523"] = {"id":"PH-H9523","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11078_2018.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将 Calamba 市从拉古纳省第二立法选区分离，构成 Calamba 市单一立法选区的法案","en":"An Act Separating the City of Calamba From the Second Legislative District of the Province of Laguna to Constitute the Lone Legislative District of the City of Calamba","orig":"An Act Separating the City of Calamba From the Second Legislative District of the Province of Laguna to Constitute the Lone Legislative District of the City of Calamba"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11078","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-24","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11078_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9523-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Lone Legislative District. - The City of Calamba is hereby separated from the Second Legislative District of the Province of Laguna to constitute the Lone Legislative District of the City of Calamba, which shall commence in the next national election after the effectivity of this Act."}},{"id":"PH-H9523-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Holdover. - The incumbent Representative of the present Second Legislative District of the Province of Laguna shall continue to represent the said district until the new Representative shall have been duly elected and qualified."}},{"id":"PH-H9523-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Rules and Regulations. - The Commission on Elections shall issue the necessary rules and regulations to implement this Act within thirty (30) days after its effectivity."}},{"id":"PH-H9523-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause. - All laws, rules and regulations which are inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9523-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the City of Calamba From the Second Legislative District of the Province of Laguna to Constitute the Lone Legislative District of the City of Calamba","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9524"] = {"id":"PH-H9524","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11079_2018.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"规定将 Maasin 市学院并入南莱特州立大学（SLSU）的法案","en":"An Act Mandating the Integration of the Maasin City College Into the Southern Leyte State University (SLSU)","orig":"An Act Mandating the Integration of the Maasin City College Into the Southern Leyte State University (SLSU)"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 11079","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11079_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9524-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Maasin City College in Maasin City, Southern Leyte is hereby integrated into the Southern Leyte State University (SLSU) and shall be known as the Southern Leyte State University - Maasin City Campus."}},{"id":"PH-H9524-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets, real and personal, personnel and records of the Maasin City College, as well as liabilities or obligations, are hereby transferred to the SLSU. The positions, rights, and security of tenure of faculty members and personnel employed at the Maasin City College under existing personnel employed at the Maasin City College under existing laws prior to the integration into the SLSU shall be respected.\nAll parcels of land belonging to the government occupied by the Maasin City College are hereby declared to be the property of the SLSU and shall be titles under its name: Provided, That should the SLSU cease to exist or be abolished or would no longer need such parcels of land aforementioned, the same shall revert to the local government units (LGUs) concerned."}},{"id":"PH-H9524-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the initial implementation of this Act shall be charged against the current year's funding of the Maasin City College provided by the City of Maasin, Southern Leyte. The City shall continue to provide the same funding to the SLSU - Maasin City Campus until such time that its full funding requirements is included in the annual General Appropriations Act."}},{"id":"PH-H9524-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Within sixty (60) days after the effectivity of this Act, the Commission on Higher Education and the SLSU shall promulgate the necessary rules and regulations to implement this Act."}},{"id":"PH-H9524-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall effect fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Mandating the Integration of the Maasin City College Into the Southern Leyte State University (SLSU)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9525"] = {"id":"PH-H9525","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11080_2018.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉省重新划分为六个立法选区的法案","en":"An Act Reapportioning the Province of Isabela Into Six (6) Legislative Districts","orig":"An Act Reapportioning the Province of Isabela Into Six (6) Legislative Districts"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11080","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11080_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9525-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Legislative Districts. - The Province of Isabela is hereby reapportioned into six (6) legislative districts to commence in the next national and local elections after the effectivity of this Act. Each district shall be composed of the following:\n(a) FIRST LEGISLATIVE DISTRICT:\n(1) Iligan City\n(2) Cabagan\n(3) Delfin Albano\n(4) Divilacan\n(5) Maconacon\n(6) Tumauini\n(7) San Pablo\n(8) Sta. Maria\n(9) Sto. Tomas\n(b) SECOND LEGISLATIVE DISTRICT\n(1) Benito Soliven\n(2) Palanan\n(3) Naguilian\n(4) Reina Mercedes\n(5) San Mariano\n(6) Gamu\n(c) THIRD LEGISLATIVE DISTRICT:\n(1) Alicia\n(2) Cabatuan\n(3) San Mateo\n(4) Ramon\n(5) Angadanan\n(d) FOURTH LEGISLATIVE DISTRICT:\n(1) Santiago City\n(2) Cordon\n(3) Dinapigue\n(4) San Agustin\n(5) Jones\n(e) FIFTH LEGISLATIVE DISTRICT\n(1) Aurora\n(2) Burgos\n(3) Luna\n(4) Mallig\n(5) Quezon\n(6) Quirino\n(7) Roxas\n(8) San Manuel\n(f) SIXTH LEGISLATIVE DISTRICT:\n(1) Cauayan City\n(2) Echague\n(3) San Guillermo\n(4) San Isidro"}},{"id":"PH-H9525-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Incumbent Representatives. - The incumbent Representatives of the Province of Isabela shall continue to represent their respective legislative districts until the new Representatives shall have been duly elected and qualified."}},{"id":"PH-H9525-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementing Rules and Regulations. - The Commission on Elections shall issue the necessary rules and regulations to implement this Act within thirty (30) days upon the effectivity of this Act."}},{"id":"PH-H9525-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause. - All laws, rules and regulations which are inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9525-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall effect fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reapportioning the Province of Isabela Into Six (6) Legislative Districts","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9526"] = {"id":"PH-H9526","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11081_2018.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"将新比斯开省 Bayombong 退伍军人地区医院床位由两百（200）张增至五百（500）张并提升其服务与设施的法案","en":"An Act Increasing the Bed Capacity of Veterans Regional Hospital in Bayombong, Nueva Vizcaya From Two Hundred (200) to Five Hundred (500), Upgrading its Services, Facilities and...","orig":"An Act Increasing the Bed Capacity of Veterans Regional Hospital in Bayombong, Nueva Vizcaya From Two Hundred (200) to Five Hundred (500), Upgrading its Services, Facilities and..."},"level":"law","status":"active","topics":["health","defence"],"docNumber":"Republic Act No. 11081","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-28","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11081_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9526-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The authorized bed capacity of the Veterans Regional Hospital in the Municipality of Bayombong, Province of Nueva Vizcaya is hereby increased from two hundred (200) to five hundred (500) beds."}},{"id":"PH-H9526-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Veterans Regional Hospital shall now be known as the Region II Trauma and Medical Center."}},{"id":"PH-H9526-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The existing facilities and professional health care services of the Region II Trauma and Medical Center are hereby upgraded to conform and be commensurate to the increase in its authorized bed capacity as provided for in Section 1 hereof."}},{"id":"PH-H9526-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The existing workforce of the Region II Trauma and Medical Center shall also be correspondingly increased. The Department of Health shall, in coordination with the Department of Budget and Management and the Civil Service Commission, and after consultation with the Region II Trauma and Medical Center, determine the additional plantilla positions to be created and filled up."}},{"id":"PH-H9526-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The increase in bed capacity of the Region II Trauma and Medical Center from two hundred (200) to five hundred (500) beds shall be implemented for a period of not more than three (3) years from the approval of this Act."}},{"id":"PH-H9526-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Secretary of Health shall immediately include in the Department's program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9526-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall effect fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of Veterans Regional Hospital in Bayombong, Nueva Vizcaya From Two Hundred (200) to Five Hundred (500), Upgrading its Services, Facilities and...","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9527"] = {"id":"PH-H9527","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11082_2018.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉省 Santiago 市南伊莎贝拉综合医院提升为名为南伊莎贝拉医疗中心的三级综合医院的法案","en":"An Act Upgrading the Southern Isabela General Hospital in Santiago City, Province of Isabela Into a Tertiary General Hospital to Be Known as the Southern Isabela Medical Center and...","orig":"An Act Upgrading the Southern Isabela General Hospital in Santiago City, Province of Isabela Into a Tertiary General Hospital to Be Known as the Southern Isabela Medical Center and..."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 11082","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-28","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11082_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9527-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Southern Isabela General Hospital in Santiago City, Province of Isabela, is hereby upgraded into a tertiary general hospital to be known as the Southern Isabela Medical Center (SIMC) which shall be under the direct technical and administrative supervision of the Department of Health (DOH)."}},{"id":"PH-H9527-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The authorized bed capacity of the SIMC is hereby increased from fifty (50) to three hundred fifty (350) beds.\nThe Secretary of the DOH shall implement the increase in bed capacity of the SIMC over a period of five (5) years from the approval of this Act."}},{"id":"PH-H9527-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The existing service capability, professional health care services and health human resource of the SIMC shall be upgraded and increased to conform with and be commensurate to the increase in authorized bed capacity as herein provided.\nThe Secretary of the Department of Budget and Management (DBM) shall create regular plantilla positions for health personnel required of a medical center, in consultation with the DOH, with the corresponding increases in the maintenance and other operating expenses (MOOE) and personal services (PS) for the SIMC."}},{"id":"PH-H9527-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Health shall immediately include in the Department's program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9527-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Within ninety (90) days from the approval of this Act, the Secretary of the DOH, in consultation with the Secretary of the DBM, shall promulgate the necessary rules and regulations to implement the provisions of this Act."}},{"id":"PH-H9527-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Republic Act No. 3138, establishing the Southern Isabela Emergency Hospital, and Republic Act No. 8338, upgrading it to Southern Isabela General Hospital, are hereby repealed. All other laws, decrees, orders, issuances, rules and regulations and parts thereof which are inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9527-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall effect fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Upgrading the Southern Isabela General Hospital in Santiago City, Province of Isabela Into a Tertiary General Hospital to Be Known as the Southern Isabela Medical Center and...","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9528"] = {"id":"PH-H9528","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11083_2018.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将拉乌尼翁省 Agoo 市镇拉乌尼翁医疗中心的床位增至三百（300）张以提升其服务与设施的法案","en":"An Act Upgrading the Services and Facilities of the La Union Medical Center in the Municipality of Agoo, Province of La Union by Increasing its Bed Capacity to Three Hundred (300) and...","orig":"An Act Upgrading the Services and Facilities of the La Union Medical Center in the Municipality of Agoo, Province of La Union by Increasing its Bed Capacity to Three Hundred (300) and..."},"level":"law","status":"active","topics":["labor","health"],"docNumber":"Republic Act No. 11083","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-28","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11083_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9528-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The services and facilities of the La Union Medical Center (LUMC) in the Municipality of Agoo, Province of La Union shall be upgraded and, accordingly, its bed capacity shall be increased from one hundred (100) to three hundred (300) beds, and a trauma center shall be established therein. The increase in bed capacity shall be done gradually over a three (3)-year period."}},{"id":"PH-H9528-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The LUMC, through its Board of Trustees, is hereby authorized to increase and hire additional employees corresponding to the upgrading of its services and facilities and increase in bed capacity. The Chief of Hospital of the LUMC shall coordinate with the Department of Health,, the Department of Budget and Management and the Civil Service Commission for the efficient and effective implementation of this Act."}},{"id":"PH-H9528-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Provincial Government of La Union and the LUMC are hereby authorized to provide the funds from their respective budgets necessary for the implementation of this Act."}},{"id":"PH-H9528-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Health, shall include in the Department's program the subsidy support for the capital outlay requirements of the said medical center."}},{"id":"PH-H9528-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, decrees, ordinances, rules and regulations, executive or administrative orders, and other presidential issuances inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9528-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall effect fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Upgrading the Services and Facilities of the La Union Medical Center in the Municipality of Agoo, Province of La Union by Increasing its Bed Capacity to Three Hundred (300) and...","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9529"] = {"id":"PH-H9529","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11084_2018.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"将碧瑶综合医院与医疗中心床位由五百（500）张增至八百（800）张并为其拨款的法案","en":"An Act Increasing the Bed Capacity of the Baguio General Hospital and Medical Center From Five Hundred (500) to Eight Hundred (800) Beds and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Baguio General Hospital and Medical Center From Five Hundred (500) to Eight Hundred (800) Beds and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 11084","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-28","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11084_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9529-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Baguio General Hospital and Medical Center (BGHMC) in Baguio City is hereby increased from five hundred (500) to eight hundred (800)."}},{"id":"PH-H9529-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The existing service facilities and professional health care services are also hereby upgraded to conform with and be commensurate to the bed capacity increase as provided in Section 1 hereof."}},{"id":"PH-H9529-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The existing workforce of the BGHMC shall also be correspondingly increased. The Department of Health, in coordination with the Department of Budget and Management and the Civil Service Commission, shall determine the additional plantilla positions to be created and filled up upon prior consultation with the BGHMC."}},{"id":"PH-H9529-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The increase in bed capacity of the BGHMC from five hundred (500) to eight hundred (800) beds shall be implemented for a period of not more than three (3_ years from the approval of this Act."}},{"id":"PH-H9529-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Health shall immediately include in the Department's program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9529-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Republic Act No. 8634, otherwise known as \"An Act Increasing the Bed Capacity of the Baguio General Hospital and Medical Center, Located in Baguio City, from Four Hundred (400) to Five Hundred (500) Beds, Upgrading the Service Facilities and Professional Health Care Therein, and Appropriating Funds Therefor\", is hereby repealed."}},{"id":"PH-H9529-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Baguio General Hospital and Medical Center From Five Hundred (500) to Eight Hundred (800) Beds and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9530"] = {"id":"PH-H9530","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11085_2018.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将新怡诗夏省 Talavera 市镇 Dr. Paulino J. Garcia 纪念研究医疗中心附属医院提升为二级医院的法案","en":"An Act Upgrading the Dr. Paulino J. Garcia Memorial Research and Medical Center Extension Hospital in the Municipality of Talavera, Province of Nueva Ecija, to a Level II Hospital and...","orig":"An Act Upgrading the Dr. Paulino J. Garcia Memorial Research and Medical Center Extension Hospital in the Municipality of Talavera, Province of Nueva Ecija, to a Level II Hospital and..."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 11085","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-09-28","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11085_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9530-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Dr. Paulino J. Garcia Memorial Research and Medical Center Extension Hospital in the Municipality of Talavera, Province of Nueva Ecija, is hereby upgraded into a Level II Hospital to be now known as the Talavera General Hospital.\nThe authorized bed capacity of the Talavera General Hospital is hereby increased from fifty (50) to one hundred (100) beds.\nThe Secretary of the Department of Health (DOH) shall implement the increase in bed capacity of the Talavera General Hospital within a period of five (5) years from the approval of this Act."}},{"id":"PH-H9530-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The existing hospital facilities and professional health care services of the Talavera General Hospital are hereby upgraded to conform with and be commensurate to the increase in bed capacity. The number of medical personnel shall be correspondingly increased."}},{"id":"PH-H9530-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall immediately include in the Department's program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9530-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Republic Act No. 8527, increasing the bed capacity of Dr. Paulino J. Garcia Memorial Research and Medical Center Extension Hospital is hereby repealed. All other laws, decrees, orders, issuances, rules and regulations and parts thereof which are inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H9530-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Within sixty (60) days after the approval of this Act, the DOH shall promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H9530-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Upgrading the Dr. Paulino J. Garcia Memorial Research and Medical Center Extension Hospital in the Municipality of Talavera, Province of Nueva Ecija, to a Level II Hospital and...","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9531"] = {"id":"PH-H9531","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11086_2018.html","fetchedAt":"2026-10-06","articleCount":60,"structureMode":"ARTICLE","title":{"zh":"将Sto. Tomas镇改制为Sto市","en":"An Act Converting the Municipality of Sto. Tomas in the Province of Batangas Into a Component City to Be Known as the City of Sto. Tomas","orig":"An Act Converting the Municipality of Sto. Tomas in the Province of Batangas Into a Component City to Be Known as the City of Sto. Tomas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11086","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-05","completenessNote":"全文，共 60 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11086_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9531-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the \"Charter of the City of Sto. Tomas\"."}},{"id":"PH-H9531-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The City of Sto. Tomas. — The Municipality of Sto. Tomas shall be converted into a component city to be known as the City of Sto. Tomas, hereinafter referred to as the City, which shall comprise the present territory of the Municipality of Sto. Tomas, Province of Batangas.\nThe territorial jurisdiction of the City shall be within the present metes and bounds of the Municipality of Sto. Tomas.\nThe foregoing provision shall be without prejudice to the resolution by the appropriate agency or forum of any boundary dispute or case involving questions of territorial jurisdiction between the City of Sto. Tomas and the adjoining local government units: Provided, That the territorial jurisdiction of the disputed area or areas shall remain with the local government unit which has existing administrative supervision over said area or areas until the final resolution of the case."}},{"id":"PH-H9531-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Corporate Powers of the City. – The City constitutes a political body corporate and as such is endowed with the attributes of perpetual succession and possessed of the powers which pertain to a municipal corporation to be exercised in conformity with the provision of this Charter. The City shall have the following corporate powers:\n(a) To have a continuous succession in its corporate name;\n(b) To sue and be sued;\n(c) To have and use a corporate seal;\n(d) To acquire, hold and convey real or personal property;\n(e) To enter into any contract and/or agreement; and\n(f) To exercise such other powers, prerogatives or authority subject to the limitations provided under Republic Act No. 7160, otherwise known as the \"Local Government Code of 1991, as amended\", this Act or laws."}},{"id":"PH-H9531-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"General Powers. – The City shall have a common seal and may alter the same at pleasure: Provided, That any change of corporate seal shall be registered with the Department of the Interior and Local Government (DILG).\nIt shall exercise the powers to levy taxes, fees and charges; to close and open roads, streets, alleys, parks or squares; to take, purchase, receive, hold, lease, convey and dispose of real and personal property for the general interests of the City; to expropriate or condemn private property for public use; to contract and to be contracted with; to sue and be sued; to prosecute and defend to final judgment and execution suits wherein the City is involved or interested in; and to exercise all the powers as are granted to corporations or as hereinafter conferred."}},{"id":"PH-H9531-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Liability for Damages. – The City and its officials shall not be exempt from liability for death or injury to persons or damage to property."}},{"id":"PH-H9531-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Jurisdiction of the City. – The jurisdiction of the City, for police purposes only, shall be coextensive with its territorial jurisdiction and, for the purpose of protecting and ensuring the purity of the water supply of the City, such police jurisdiction shall also extend over all the territory within the drainage area of such water supply, or within one hundred meters (100m.) of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service.\nThe city court of the City of Sto. Tomas and the city or municipal courts of the adjoining cities and municipalities shall have concurrent jurisdiction to try crimes and misdemeanors committed within said drainage area or areas within said spaces of one hundred meters (100m.) of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service delivery.\nThe court first taking cognizance of such an offense shall have jurisdiction to try cases to the exclusion of others. The police forces of the municipalities and cities concerned shall have concurrent jurisdiction with the police forces of the City for the maintenance of good order and the enforcement of ordinances throughout said zone, area or space shall be granted by the proper authorities of the city or municipality concerned, and the fees arising therefrom shall accrue to the treasury of the said city or municipality concerned and not to the City.\nCITY OFFICIALS IN GENERAL"}},{"id":"PH-H9531-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The Officials of the City of Sto. Tomas. – (a) There shall be in the City of Sto. Tomas: a City Mayor, a City Vice Mayor, Sangguniang Panglungsod members, a secretary to the Sangguniang Panlungsod , a city treasurer, a city assessor, a city accountant, a city budget officer, a city planning and development officer, a city engineer, a city health officer, a city civil registrar, a city administrator, a city legal officer, a city social welfare and development officer, a city veterinarian and a city general services officer.\n(b) In addition thereto, the City Mayor may appoint a city environment and natural resources officer, a city architect, a city information officer, a city cooperatives officer, a city population officer and a city agriculturist.\n(c) There shall be established in the City a city fire station to be headed by a city fire marshal, a city jail to be headed by a city jail warden, a city schools division to be headed by a city schools division superintendent and a city prosecution service to be headed by a city prosecutor.\n(d) The Sangguniang Panlungsod may:\n(1) Maintain existing offices not mentioned in subsections (a) and (b) hereof;\n(2) Create such other offices as may be necessary to carry out the purposes of the City; or\n(3) Consolidate the functions of any office with those of another in the interest of efficiency and economy.\n(e) Unless otherwise provided herein, heads of departments and offices shall be appointed by the City Mayor with the concurrence of the majority of all the Sangguniang Panlungsod members, subject to civil service laws, rules and regulations. The Sangguniang Panlungsod shall act on the appointment within fifteen (15) days from the date of its submission, otherwise the same shall be deemed confirmed.\n(f) Elective and appointive city officials shall receive compensation, allowances and other emoluments as may be determined by law or ordinance, subject to the budgetary limitations on personal services prescribed under Title Five, Book II of the Local Government Code of 1991, as amended: Provided, That no increase in the compensation of the City Mayor, City Vice Mayor and Sangguniang Panlungsod member shall take effect until after the expiration of the full term of the local officials approving the increase.\nTHE CITY MAYOR AND CITY VICE MAYOR"}},{"id":"PH-H9531-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The City Mayor. – (a) The City Mayor shall be the chief executive of the City and shall be elected at large by the qualified voters of the City. No person shall be eligible for the position of City Mayor unless, at the time of the election, that person is a citizen of the Philippines, at least twenty-one (21) years of age, a resident of the City for at least one (1) year immediately preceding the day of the election and a qualified registered voter therein, and is able to read and write Filipino or any other local language or dialect. The City Mayor shall hold office for three (3) years, unless sooner removed, but shall serve for not more than three (3) consecutive terms in the same position. The City Mayor shall receive a minimum monthly compensation corresponding to Salary Grade Thirty (30) as prescribed under Republic Act No. 6758, as amended, otherwise known as the \"Compensation and Position Classification Act of 1989\", and the implementing guidelines issued pursuant thereto.\nThe City Mayor, as the Chief Executive of the City Government, shall exercise such powers and perform such duties and functions as provided under the Local Government Code of 1991, as amended, this Act, and other laws.\n(b) For efficient, is effective and economical governance, the purpose of which is the general welfare of the City and its inhabitants, the City Mayor shall:\n(1) Exercise general supervision and control over all programs, projects, services, and activities of the city government and, in this connection, shall:\n(i) Determine the guidelines of city policies and be responsible to the Sangguniang Panlungsod for the program of government;\n(ii) Direct the formulation of the city development plan, with the assistance of the city development council and, upon approval thereof by the Sangguniang Panlungsod , implement the same;\n(iii) Present the program of government and propose policies and projects for the consideration of the Sangguniang Panlungsod at the opening of the regular session of the Sangguniang Panlungsod every calendar year and as often as may be deemed necessary as the general welfare of the inhabitants and the needs of the city government may require;\n(iv) Initiate and propose legislative measures to the Sangguniang Panlungsod and, as often as may be deemed necessary, provide such information and data needed or requested by said Sanggunian in the performance of its legislative functions;\n(v) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of city funds and whose appointments are not otherwise provided for under the Local Government Code of 1991, as amended, and in this Act, and those whose appointment he or she may be authorized by laws to appoint;\n(vi) Represent the City in all its business transactions and sign on its behalf all bonds, contracts and obligations, and other documents upon the authority of the Sangguniang Panlungsod or pursuant to law or ordinance;\n(vii) Carry out emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(viii) Determine the time, manner and place of payment of salaries or wages of the officials and employees of the City, in accordance with law or ordinance;\n(ix) Allocate and assign office space to the City and other officials and employees who, by law or ordinance, are entitled to space in the city hall and other buildings owned or leased by the city government;\n(x) Ensure that all executive officials and employees of the City faithfully discharge their duties and functions as provided for by law and the Local Government Code of 1991, as amended, and cause to be instituted administrative or judicial proceedings against any official or employee of the City who may have committed an offense in the performance of official duties;\n(xi) Examine the books, records and other documents of all offices, officials, agents or employees of the City and, in aid of executive powers and authority, require all national officials and employees stationed in or assigned to the City to make available books, records and other documents in their custody, except those classified by law as confidential;\n(xii) Furnish copies of executive orders issued to the provincial governor within seventy-two (72) hours after their issuance;\n(xiii) Visit component barangays of the City at least once every six (6) months to deepen understanding of the problems and conditions, listen and give appropriate counsel to local officials and inhabitants, inform the component barangay officials and inhabitants of general laws and ordinances which especially concern them, and otherwise conduct visits and inspections to ensure that the governance of the City will improve the quality of life of the inhabitants;\n(xiv) Act on leave applications of officials and employees appointed by him or her and on the communication of the monetary value of their leave credits in accordance with law;\n(xv) Authorize official trips of city officials and employees outside of the City for a period not exceeding thirty (30) days: Provided, That trips abroad for a longer period may be authorized in accordance with the Local Government Code of 1991, as amended;\n(xvi) Call upon any national official or employee stationed in or assigned to the City for advice on matters affecting the City and to make recommendations threon; coordinate with the officials and employees in the formulation and the implementation of plans, programs and projects; and, when appropriate, initiate an administrative or judicial action against a national government official or employee who may have committed an offense in the performance of official duties while stationed in or assigned to the City;\n(xvii) Authorize payment for medical care, necessary transportation, subsistence, hospital or medical fees of city officials and employees who are injured while in the performance of their official duties and functions, subject to the availability of funds;\n(xviii) Solemnize marriages, any provision of law to the contrary notwithstanding;\n(xix) Conduct an annual palarong panlungsod which shall feature traditional sports and disciplines included in national international games, in coordination with the Department of Education (DepEd); and\n(xx) Submit to the provincial governor the following reports: an annual report containing a summary of all matters pertinent to the management, administration and development of the City and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situations arise at any time during the year, particularly when man-made and natural disasters or calamities affect the general welfare of the City;\n(2) Enforce all laws and ordinances relative to the governance of the City and in the exercise of its appropriate corporate powers, as well as implement all approved policies, programs, projects, services and activities of the City; and, in addition, shall:\n(i) Ensure that the acts of the City’s component barangays and of its officials and employees are within the scope of their prescribed powers, duties and functions;\n(ii) Call conventions, conferences, seminars or meetings of elective and appointive officials of the City, including national and provincial officials and employees stationed in or assigned to the City, at such time and place and on subjects as may be deemed important for the promotion of the general welfare of the local government unit and its inhabitants;\n(iii) Issue executive orders for the faithful and appropriate enforcement and execution of laws and ordinances;\n(iv) Be entitled to carry the necessary firearms within his or her territorial jurisdiction;\n(v) Act as the deputized representative of the National Police Commission, formulate the peace and order plan of the City and, upon its approval, implement the same, and as such, exercise general and operational control and supervision over local police forces in the City in accordance with Republic Act No. 6975, otherwise known as the \"Department of the Interior and Local Government Act of 1990\"; and\n(vi) Call upon the law enforcement agencies to suppress disorder, riot, lawless violence, rebellion, sedition, or apprehend violators of the law when public interest so requires and the city police forces are inadequate to cope with the situation or the violators;\n(3) Initiate and maximize the generation of resources and revenues, and apply the same to the implementation of development plans, program objectives and priorities, particularly those resources and revenues programmed for agro-industrial development and countryside growth and progress and, relative thereto, shall:\n(i) Require each head of an office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparation process enshrined under Republic Act No. 7160, as amended, otherwise known as the \"Local Government Code of 1991\";\n(ii) Prepare and submit to the Sanggunian for approval the executive and supplemental budgets of the City for the ensuing calendar year in the manner provided for under the Local Government Code of 1991, as amended;\n(iii) Ensure that all taxes and other revenues of the City are collected, and that city funds are applied to the payment of expenses and the settlement of obligations of the City, in accordance with law or ordinance;\n(iv) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which the licenses or permits had been issued, pursuant to law or ordinance;\n(v) Issue permits, without need of approval from any national agency, for the holding of activities for any charitable or welfare purpose, excluding prohibited games of chance or shows contrary to law, public policy and public morals;\n(vi) Require owners of illegally constructed houses, buildings or other structures to obtain the necessary permits, subjects to fines and penalties as may be imposed by law or ordinance, or to make necessary changes in their construction when violative of any law or ordinance, or to order the demolition or removal of house, building or structure within the period prescribed by law or ordinance;\n(vii) Adopt adequate measures to safeguard and conserve land, mineral, marine, forest and other resources of the City;\n(viii) Provide efficient and effective property and supply management in the City and protect the funds, credits, rights and other properties of the City; and\n(ix) Institute or cause to be instituted administrative or judicial proceedings for violation of ordinances in the collection of taxes, fees, charges, and for the recovery of funds and property; and cause the City to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected;\n(4) Ensure the delivery of basic services and the provision of adequate facilities and, in addition thereto, shall:\n(i) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out, in a spatially contiguous manner and in coordination with the construction and repair of the roads and bridges of the City and of the Province; and\n(ii) Coordinate the implementation of technical services, including public works and infrastructure programs, rendered by national offices; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance.\n(c) During the incumbency of the City Mayor, he or she shall hold office in the city hall."}},{"id":"PH-H9531-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The City Vice Mayor. – (a) There shall be a City Vice Mayor who shall be elected in the same manner as the City Mayor and shall, at the time of the election, possess the same qualifications as the City Mayor. The City Vice Mayor shall hold office for three (3) years, unless sooner removed, and shall receive a monthly compensation corresponding to Salary Grade Twenty-six (26) as prescribed under the \"Compensation and Position Classification Act of 1989\", as amended, and the implementing guidelines issued pursuant thereto.\n(b) The City Vice Mayor shall:\n(1) Be the presiding officer of the Sangguniang Panlungsod and shall sign all warrants drawn on the City Treasury for all expenditures appropriated for the operation of the Sangguniang Panlungsod ;\n(2) Subject to civil service law, rules and regulations, appoint all officials and employees of the Sangguniang Panlungsod , except those whose manner of appointment is specifically provided for under the Local Government Code of 1991, as amended;\n(3) Assume the office of the City Mayor for the unexpired term of the latter in the event of permanent vacancy as provided for under the Local Government Code of 1991, as amended;\n(4) Exercise the powers and perform the duties and functions of the City Mayor in case of temporary vacancy as provided for under the Local Government Code of 1991, as amended; and\n(5) Perform other duties and functions and exercise other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance.\nTHE SANGGUNIANG PANLUNGSOD"}},{"id":"PH-H9531-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Composition. – (a) The Sangguniang Panlungsod , the legislative body of the City, shall be composed of the City Vice Mayor as the presiding officer, the ten (10) regular Sanggunian members, the President of the City Chapter of the Liga ng mga Barangay, the President of the City Chapter of the Liga ng mga Barangay, the President of the Panlungsod na Pederasyon ng mga Sangguniang Kabataan and the three (3) sectoral representatives, who shall come from the following sectors, as members: one (1) from the women sector; and, as shall be determined by the Sangguniang Panlungsod within ninety (90) days prior to the holding of the local elections; one (1) from the agricultural or industrial workers sector; and one (1) from the other sectors, including urban poor, indigenous cultural communities or persons with disabilities (PWDs).\n(b) The regular members of the Sangguniang Panlungsod and sectoral representatives shall be elected in the manner as may be provided by law.\n(c) The members of the Sangguniang Panlungsod shall receive a minimum monthly compensation corresponding to Salary Grade Twenty-five (25) as prescribed under the \"Compensation and Position Classification Act of 1989\", as amended, and implementing guidelines issued pursuant thereto."}},{"id":"PH-H9531-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Powers, Duties, Functions and Compensation. – The Sangguniang Panlungsod, as the legislative body of the City, shall enact ordinances, approve resolutions and appropriate funds for the general welfare of the City and its inhabitants pursuant to Section 16 of the Local Government Code of 1991, as amended, and in the proper exercise of the corporate powers of the City as provided for under Section 22 of the Local Government Code of 1991, as amended, and shall:\n(1) Approve ordinances and pass resolutions necessary for an efficient and effective city government and, in this connection, shall:\n(i) Review all ordinances approved by the Sangguniang Barangay and executive orders issued by the Punong Barangay to determine whether these are within the scope of the prescribed powers of the Sangguniang Barangay and of the Punong Barangay;\n(ii) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for the violation of ordinances;\n(iii) Approve ordinances imposing a fine not exceeding Five thousand pesos (P5,000.00) or imprisonment for a period not exceeding one (1) year, or both, at the discretion of the court, for violation of a city ordinance;\n(iv) Adopt measures to protect the inhabitants of the City from the harmful effects of man-made or natural disasters and calamities, and to provide relief services and assistance to victims during and in the aftermath of said disasters or calamities and in their return to productive livelihood following said events;\n(v) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, the establishment and maintenance of house of ill-repute, illegal gambling and other prohibited games of chance, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution or exhibition of obscene or pornographic materials to the welfare and morals of the inhabitants of the City;\n(vi) Protect the environment and impose appropriate penalties for acts which endanger the environment, such as dynamite fishing and other forms of destructive fishing, illegal logging, smuggling of logs, smuggling of natural resources products and of endangered species of flora and fauna, slash-and-burn farming and such other activities which result in pollution, acceleration of siltation of rivers and lakes or of ecological imbalance;\n(vii) Subject to the provisions of the Local Government Code of 1991, as amended, and other pertinent laws, determine the powers and duties of officials and employees of the City;\n(viii) Determine the positions and the salaries, wages, allowances and other emoluments and benefits of officials and employees paid wholly or mainly from the city funds and provide for expenditures necessary for the proper conduct of programs, projects, services and activities of the city government;\n(ix) Authorize the payment of compensation to a qualified person not in the government service who fills in a temporary vacancy or grant honoraria to any qualified official or employee designated to fill in a temporary vacancy in a concurrent capacity at the rate authorized by law;\n(x) Provide a mechanism and the appropriate funds therefor for the safety and protection of all city government properties, public documents or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits and such other records and documents of public interest in the offices and departments of the city government;\n(xi) When the finances of the city government allow, provide for additional alloances and other benefits to judges, prosecutors, public elementary and high school teachers, and other national government employees stationed in or assigned to the City;\n(xii) Provide legal assistance to barangay officials who, in the performance of their official duties or on the occasion thereof, have to initiate judicial proceedings or defend themselves against legal action; and\n(xiii) Provide for group insurance or additional insurance coverage for all barangay officials, including members of barangay tanod brigades and service units, with public or private insurance companies, when the finances of the city government allow coverage;\n(2) Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the City, as provided for under the Local Government Code of 1991, as amended, with particular attention to agro-industrial development and citywide growth and progress and, relative thereto, shall:\n(i) Approve the annual and supplemental budgets of the city government and appropriate funds for specific programs, projects, services and activities of the City, or for other purposes not contrary to law, in order to promote the general welfare of the City and its inhabitants;\n(ii) Subject to the provisions of Book II of the Local Government Code of 1991, as amended, and applicable laws and, upon the majority vote of all the members of the Sangguniang Panlungsod, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes and granting tax exemptions, incentives or reliefs;\n(iii) Subject to the provisions of Book II of the Local Government Code of 1991, as amended, and upon the majority vote of all the members of the Sangguniang Panlungsod, authorize the City Mayor to negotiate and contract loans and other forms of indebtedness;\n(iv) Subject to the provisions of Book II of the Local Government Code of 1991, as amended, and applicable laws and, upon the majority vote of all the members of the Sangguniang Panlungsod, enact ordinances authorizing the floating of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(v) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the City and, upon the majority vote of all the members of the Sangguniang Panlungsod, authorize the City Mayo to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(vi) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the City;\n(vii) Adopt a comprehensive land-use plan for the City and ensure that the formulation, adoption or modification of said plan shall be in coordination with the approved provincial comprehensive land-use plan;\n(viii) Reclassify lands within the jurisdiction of the City, subject to the pertinent provisions of the Local Government Code of 1991, as amended;\n(ix) Enact integrated zoning ordinances in consonance with the approved comprehensive land-use plan, subject to existing laws, rules and regulations; establish fire limits or zones, particularly in populous centers; and regulate the construction, repair or modification with the provisions of the Fire Code of the Philippines;\n(x) Subject to national law, process and approve subdivision plans for residential, commercial or industrial purposes and other development purposes, and to collect processing fees and other charges, the proceeds of which shall accrue entirely to the City: Provided, however, That where approval of a national agency or office is required, said approval shall not be withheld for more than thirty (30) days from receipt of the application. Failure to act on the application within the period stated above shall be deemed as approval threof;\n(xi) Subject to the provisions of Book II of the Local Government Code of 1991, as amended, grant exclusive privilege of constructing fish corrals or fish pens, or taking or catching of bangus fry, prawn fry or kawag-kawag, or fry of any specied or fish within the city waters;\n(xii) With the concurrence of at least two-thirds (2/3) vote of all members of the Sangguniang Panlungsod, grant tax exemptions, incentives or reliefs to entities engaged in community growth-inducing industries, subject to the provisions of the Local Government Code of 19914, as amended;\n(xiii) Grant loans or provide grants to other local government units or to national, provincial and city charitable, benevolent or educational institutions: Provided, That the institutions are operated and maintained within the City;\n(xiv) Regulate the numbering of residential, commercial and other buildings; and\n(xv) Regulate the inspection, weighing and measuring of articles of commerce;\n(3) Subject to the provisions of Book II of the Local Government Code of 1991, as amended, enact ordinances granting franchises and authorizing the issuance of permits or licenses, upon the conditions and for purposes intended to promote the general welfare of the inhabitants of the City and, pursuant to this legislative authority, shall:\n(i) Fix and impose reasonable fees and charges for all services rendered by the city government to private persons or entities;\n(ii) Regulate or fix license fees for any business or practice of profession within the City and the conditions under which the license for the business or practice of profession may be revoked, and enact ordinances levying taxes thereon;\n(iii) Provide for and set the terms and conditions under which public utilities owned by the City shall be operated by the city government and prescribe the conditions under which the same may be leased to private persons or entities, preferably cooperatives;\n(iv) Regulate the display of and fix the license fees for signs, signboards or billboards at the place or places where the profession or business advertised thereby is, in whole or in part, conducted;\n(v) Any law to the contrary notwithstanding, authorize and license the establishment, operation and maintenance of cockpits, and regulate cockfighting and commercial breeding of gamecocks: Provided, That existing rights should not be prejudiced;\n(vi) Subject to the guidelines prescribed by the Department of Transportation (DOTr), regulate the operation of tricycles and grant franchises for the operation thereof within the territorial jurisdiction of the City; and\n(vii) Upon approval by a majority vote of all the members of the Sangguniang Panlungsod, grant a franchise to any person, partnership, corporation or cooperative to do business within the City; establish, construct, operate and maintain ferries, wharves, markets or slaughterhouses; or undertake other activities within the City as may be allowed by existing laws: Provided, That cooperatives shall be given preference in the grant of franchise;\n(4) Regulate activities relative to the use of land, buildings and structures within the City in order to promote the general welfare and, for the said purpose, shall:\n(i) Declare, prevent or abate any nuisance;\n(ii) Require that buildings and the premises thereof and any land within the City be kept and maintained in a sanitary condition; impose penalties for any violation thereof; or upon failure to comply with the said requirement, have the work done at the expense of the owner, administrator or tenant concerned; and require the filling up of any land or premises to a grade necessary for proper sanitation;\n(iii) Regulate the disposal of clinical and other wastes from hospitals, clinics and other similar establishments;\n(iv) Regulate the establishment, operation and maintenance of restaurants, beerhouses, hotels, motels, inns, pension houses, lodging houses and other similar establishments, including tourist guides and transports;\n(v) Regulate the sale, giving away or dispensing of any intoxicating malt, vino, mixed or fermented liquors at any retail outlet;\n(vi) Regulate the establishment and provide for the inspection of steam boilers or any heating device in buildings and the storage of inflammable and highly combustible materials within the City;\n(vii) Regulate the establishment, operation and maintenance of any entertainment or amusement facility, including the theatrical performances, circuses, billiard halls, public dancing schools, public dance halls, sauna baths, massage parlors, and other places for entertainment or amusement; regulate such other events or activities for amusement or entertainment, particularly those which tend to disturb the community or annoy the inhabitants, or require the suspension or suppression of the same; or prohibit certain forms of amusement or entertainment in order to protect the social and moral welfare of the community;\n(viii) Provide for the impounding of stray animals; regulate the keeping of animals in homes or as part of a business, and the slaughter, sale or disposition of the same; and adopt measures to prevent and penalize cruelty to animals; and\n(ix) Regulate the establishment, operation and maintenance of funeral parlors and the burial or cremation of the dead, subject to existing laws, rules and regulations;\n(5) Approve ordinances which shall ensure the efficient and effective delivery of basic services and facilities as provided for under the Local Government Code of 1991, as amended, and, in addition to said services and facilities, shall:\n(i) Provide for the establishment, maintenance, protection and conservation of communal forests and watersheds, tree parks and greenbelts, mangroves, and other similar forest development projects;\n(ii) Establish markets, slaughterhouses or animal corrals and authorize the operation thereof by the city government; and regulate the construction and operation of private markets, talipapas or other similar buildings and structures;\n(iii) Authorize the establishment, maintenance and operation by the city government of ferries, wharves, and/or other structures intended to accelerate productivity related to marine life and seashore or offshore activities in the preservation thereof;\n(iv) Regulate the preparation and sale of meat, poultry, fish, vegetables, fruits, fresh dairy products, and other foodstuffs for public consumption;\n(v) Regulate the use of streets, avenues, alleys, sidewalks, bridges, parks and other public places and approve the construction, improvement, repair and maintenance of the same; establish bus and vehicle stops and terminals or regulate the use of the same by privately-owned vehicles which serve the public; regulate garages and the operation of conveyances for hire; designate stands to be occupied by public vehicles when not in use; regulate the putting up of signs, signposts, awnings and awning posts on the streets; and provide for the lighting, cleaning and sprinkling of streets and public places;\n(vi) Regulate traffic on all streets and bridges, prohibit encroachments or obstacles thereon and, when necessary in the interest of public welfare, authorize the removal of encroachments and illegal constructions in public places;\n(vii) Subject to existing laws, establish and provide for the maintenance, repair and operation of an efficient waterworks system to supply water for the City’s inhabitants and to purify the source of the water supply; regulate the construction, maintenance, repair and use of hydrants, pumps, cisterns and reservoirs; protect the purity and the quantity of the water supply of the City and, for this purpose, extend the coverage of appropriate ordinances over all territories within the drainage area of said water supply within one hundred meters (100 m.) of the reservoir, canal, conduit, aqueduct, pumping station or watershed used in connection with the water service; and regulate the consumption, use or wastage of water and fix and collect charges thereof;\n(viii) Regulate the drilling and excavation of the ground for the laying of water, gas, sewer and other pipes and the construction, repair and maintenance of public drains, sewers, cesspools, tunnels and similar structures; regulate the placing of poles and the use of crosswalks, curbs and gutters; adopt measures to ensure public safety against open canals, manholes, live wires and other similar hazards to life and property; and regulate the construction and use of private water closets, privies and other similar structures in buildings and homes;\n(ix) Regulate the placing, stringing, attaching, installing, repair and construction of all gas mains, electric telegraph and telephone wires, conduits, meters and other apparatus; and provide for the correction, condemnation or removal of the same when found to be dangerous to the welfare of the City’s inhabitants;\n(x) Subject to the availability of funds and to existing laws, rules and regulations, establish and provide for the operation of vocational and technical schools and similar post-secondary institutions and, with the approval of the Technical Education and Skills Development Authority (TESDA), and subject to existing laws on tuition fees, fix and collect reasonable tuition fees and other school charges in educational institutions supported by the city government;\n(xi) Establish a scholarship fund for poor but deserving students in schools located within its jurisdiction or for students residing within the City;\n(xii) Provide for an efficient and effective system of solid waste and garbage collection and disposal and prohibit littering and the placing or throwing of garbage, refuse and other filth and wastes;\n(xiv) Provide for the care of PWDs, paupers, the elderly, the sick, persons of unsound mind, abandoned minors, juvenile delinquents, drug dependents, abused children and the youth below eighteen (18) years of age and, subject to the availability of funds, establish and provide for the operation of centers and facilities for the needy and disadvantaged persons;\n(xv) Establish and provide for the maintenance and improvement of jails and detention centers, institute a sound jail management program and appropriate funds for the subsistence of detainees and convicted prisoners in the City;\n(xvi) Establish a city council whose purpose is the promotion of culture and the arts, coordinate with government agencies and nongovernmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same; and\n(xvii) Establish a city council for the elderly and senior citizens which shall formulate policies and adopt measures mutually beneficial to the elderly and to the community; provide incentives for nongovernmental entities and, subject to the availability of funds, appropriate funds to support programs and projects for the benefit of the elderly; and\n(6) Perform other duties and functions and exercise such powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance.\nPROCESS OF LEGISLATION"}},{"id":"PH-H9531-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Internal Rules of Procedure. – (a) On the first regular session following the election of its members and within ninety (90) days thereafter, the Sangguniang Panlungsod shall adopt or update its existing rules of procedure.\n(b) The rules of procedure shall provide for the following:\n(1) The organization of the Sanggunian and the election of its officers as well as the creation of standing committees which shall include the committees on appropriations, revenues, engineering and public works, education and health, women and family, human rights, youth and sports development, environmental protection, peace and order and traffic, and cooperatives; the general jurisdiction of each committee; and the election of the chairperson and members of each committee;\n(2) The order and calendar of business for each session;\n(3) The legislative process;\n(4) The parliamentary procedures which include the conduct of members during sessions;\n(5) The discipline of members for disorderly behavior and absences without justifiable cause for four (4) consecutive sessions for which they may be censured, reprimanded or excluded from the session, suspended for not more than sixty(60) days or expelled: Provided, That the penalty of suspension or expulsion shall require the concurrence of at least two-thirds (2/3) vote of all the Sanggunian members: Provided, further, That the member convicted by final judgment to imprisonment of at least one (1) year for any crime involving moral turpitude shall be automatically expelled from the Sanggunian ; and\n(6) Such other rules as the Sanggunian may adopt."}},{"id":"PH-H9531-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Full Disclosure of Financial and Business Interests of Sangguniang Panlungsod Members. - (a) Every Sangguniang Panlungsod member shall, upon assumption to office, make a full disclosure of business and financial interests. Such disclosure shall also include professional relationship or any relation by affinity or consanguinity within the fourth civil degree with any person, firm or entity affected by any ordinance or resolution under consideration Sanggunian of which he or she is a member, which relationship may result in conflict of interests. Such relationship shall include:\n(1) Ownership of stock or capital, or investment in the entity or firm to which ordinance or resolution may apply; and\n(2) Contracts or agreements with any person or entity which ordinance or resolution may affect.\nIn the absence of a specific constitutional or statutory provision applicable to this situation, \"conflict of interest\" refers, in general, to one where it may be reasonably deduced that a member of a Sanggunian may not act in the public interest due to some private, pecuniary or other personal consideration that may tend to affect the exercise of judgment to the prejudice of the service or the public.\n(b) The disclosure required under this Act shall be made in writing and shall be submitted to the secretary of the Sanggunian or the secretary of the committee of which he or she is a member. The disclosure shall, in all cases, form part of the record of the proceedings and shall be made in the following manner:\n(1) The disclosure shall be made before the member participates in deliberations on the ordinance or resolution under consideration: Provided, That if the member did not participate during the deliberations, the disclosure shall be made before voting on the ordinance or resolution on second and third readings; and\n(2) The disclosure shall be made when a member takes a position or makes a privilege speech on a matter that may affect the business interest, financial connection or professional relationship described herein."}},{"id":"PH-H9531-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Sessions. – (a) On the first day of the session immediately following the election of its members, the Sangguniang Panlungsod shall, by resolution, fix the day, time and place of its sessions. The minimum number of regular sessions shall be once a week for the Sangguniang Panlungsod and twice a month for the Sangguniang Barangay.\n(b) When the public interest so demands, special sessions may be called by the City Mayor or by a majority of the members of the Sanggunian.\n(c) All Sanggunian sessions shall be open to the public unless a closed-door session is ordered by an affirmative vote of the majority of the members present, there being a quo rum, in the public interest or for reasons of security, decency or morality. No two (2) sessions, regular or special, may be held in a single day.\n(d) In the case of special sessions of the Sanggunian, a written notice to the members shall be served personally at the members’ usual place of residence at least twenty-four (24) hours before the special session is held.\nUnless otherwise concurred in by two-thirds (2/3) vote of the Sanggunian members present, there being a quo rum, no other matter may be considered at a special except those stated in the notice.\n(e) The Sangguniang Panlungsod shall keep a journal and a record of its proceedings, which may be published upon resolution of the majority of its members."}},{"id":"PH-H9531-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Quorum. – (a) A majority of all the members of the Sanggunian who have been elected and qualified shall constitute a quo rum to transact official business. Should a question of quorum be raised during a session, the presiding officer shall immediately proceed to call the roll of the members and thereafter announce the result.\n(b) Where there is no quorum, the presiding officer may declare a recess until such time a quo rum is constituted, or a majority of the members present may adjourn from day to day and may compel the immediate attendance of any member absent without justifiable cause by designating a member of the Sanggunian, to be assisted by a member or members of the police force assigned in the territorial jurisdiction of the City of Sto. Tomas, to arrest the absent member and present him or her at the session.\n(c) If there is still no quorum despite the enforcement of the immediately preceding subsection, no business shall be transacted. The presiding officer, upon proper motion duly approved by the members present, shall then declare the session adjourned for lack of quorum."}},{"id":"PH-H9531-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Approval of Ordinances. – (a) Every ordinance enacted by the Sangguniang Panlungsod shall be presented to the City Mayor. If the City Mayor approves the same, his or her signature shall be affixed on each and every page thereof; otherwise, the ordinace shall be vetoed and return the same with his or her statement on the objections to the Sanggunian, which any proceed to reconsider the same. The Sanggunian may override the veto of the City Mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance or resolution effective for all legal intents and purposes.\n(b) The veto shall be communicated by the City Mayor to the Sanggunian within ten (10) days; otherwise, the ordinance shall be deemed approved as if it had been signed."}},{"id":"PH-H9531-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Veto Power of the City Mayor. – (a) The City Mayor may veto any ordinance of the Sangguniang Panlungsod on the ground that it is ultra vires or prejudicial to the public welfare, stating the reasons thereof in writing.\n(b) The City Mayor shall have the power to veto any particular item or items of an appropriations ordinance, an ordinance or resolution adopting a local development plan, any public investment program or an ordinance directing the payment of money or creating liability. In such case, the vetoed item or items shall not affect the item or items which are not objected to. The vetoed item or items shall not take effect unless the Sangguniang Panlungsod overrides the veto in the manner herein provided; otherwise, the item or items in the appropriations ordinance of the previous year corresponding to those vetoed, if any, shall be deemed reenacted.\n(c) The City Mayor may veto an ordinance or resolution only once. The Sanggunian may override the veto of the City Mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance effective even without the approval of the City Mayor."}},{"id":"PH-H9531-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Review of City Ordinances by the Sangguniang Panlalawigan. – (a) Within three (3) days after approval, the secretary to the Sangguniang Panlungsod shall forward to the Sangguniang Panlalawigan for review, copies of approved ordinances and the resolutions approving the local development plans and the public investment programs formulated by the local development councils.\n(b) Within thirty (30) days after receipt of copies of such ordinances and resolutions, the Sangguniang Panlalawigan shall examine the documents or transmit them to the provincial attorney or the provincial prosecutor for prompt examination. The provincial attorney or the provincial prosecutor shall, within a period of ten (10) days from receipt of the documents, inform the Sangguniang Panlalawigan in writing of his or her comments or recommendations which may be considered by the Sangguniang Panlalawigan in making its decision.\n(c) If the Sangguniang Panlalawigan finds that such an ordinance or resolution is beyond the power conferred upon the Sangguniang Panlungsod, it shall declare such ordinance or resolution invalid in whole or in part. The Sangguniang Panlalawigan shall enter its action in the minutes and shall advise the corresponding city authorities of the action it has taken.\n(d) If no action is taken by the Sangguniang Panlalawigan within thirty (30) days after submission of such an ordinance or resolution, the same shall be presumed to be consistent with law and therefore valid."}},{"id":"PH-H9531-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Review of Barangay Ordinances by the Sangguniang Panlungsod. – (a) Within ten (10) days after its enactment, the Sangguniang Barangay shall furnish copies of all barangay ordinances to the Sangguniang Panlungsod for review as to whether the ordinances are consistent with law and city ordinances.\n(b) If the Sangguniang Panlungsod fails to take action on barangay ordinances within thirty (30) days from receipt thereof, the same shall be deemed approved.\n(c) If the Sangguniang Panlungsod finds a barangay ordinance inconsistent with law or city ordinances, the Sangguniang Panlungsod shall, within thirty (30) days from receipt thereof, return the same with its comments and recommendations to the Sangguniang Barangay concerned for adjustment, amendment or modification; in which case, the effectivity of the barangay ordinance is suspended until such time as the revision called for is effected."}},{"id":"PH-H9531-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Enforcement of Disapproved Ordinances or Resolutions. – Any attempt to enforce any ordinance or any resolution approving the local development plan and the public investment program after disapproval thereof shall be sufficient ground for the suspension or dismissal of the official or employee concerned."}},{"id":"PH-H9531-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Effectivity of Ordinances or Resolutions. – (a) Unless otherwise stated in the ordinance or the resolution approving the local development plan and the public investment program, the same shall take effect after ten (10) days from the date a copy thereof is posted in a bulletin board at the entrance of the city hall and in at least two (2) other conspicuous places in the City not later than five (5) days after approval thereof.\n(b) The secretary of the Sangguniang Panlungsod shall cause the posting of an ordinance or resolution in the bulletin board at the entrance of the city hall and in at least two (2) conspicuous places in the City not later than five (5) days after approval thereof. The text of the ordinance or resolution shall be disseminated and posted in Filipino or English, and the secretary of the Sangguniang Panlungsod shall record such fact in a book kept for the purpose, stating the dates of approval and posting.\n(c) Ordinances with penal sanctions shall be posted at prominent places in city hall, for a minimum period of three (3) consecutive weeks. Such ordinances shall also be published in a newspaper of general circulation within the City.\nDISQUALIFICATION AND SUCCESSION OF\nELECTIVE CITY OFFICIALS"}},{"id":"PH-H9531-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Disqualification of Elective City Officials. – The following persons are disqualified from running for any elective position in the City:\n(a) Those sentenced by final judgment for an offense involving moral turpitude or an offense punishable by one (1) year or more of imprisonment, within two (2) years after serving sentence;\n(b) Those removed from office as a result of an administrative case;\n(c) Those convicted by final judgment for violating the oath of allegiance to the Republic of the Philippines;\n(d) Those with dual citizenship;\n(e) Fugitives from justice in criminal or nonpolitical cases here and abroad;\n(f) Permanent residents in a foreign country or those who have acquired the right to reside abroad and continue to avail of the same right after the effectivity of the Local Government Code of 1991, as amended; and\n(g) The insane or feeble-minded."}},{"id":"PH-H9531-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Permanent Vacancy in the Offices of the City Mayor and the City Vice Mayor. - (a) If a permanent vacancy occurs in the office of the City Mayor, the City Vice Mayor shall become the City Mayor. If a permanent vacancy occurs in the office of the City Vice Mayor, the highest ranking Sangguniang Panlungsod member or, in case of his or her permanent incapacity, the second highest ranking Sangguniang Panlungsod member becomes the City Mayor or the City Vice Mayor, as the case may be. Subsequent vacancies in the said offices shall be filled automatically by the other Sanggunian members according to their ranking as defined under the Local Government Code of 1991, as amended.\n(b) If a permanent vacancy occurs in the office of the Punong Barangay , the highest ranking Sangguniang Barangay member or, in case of his or her permanent incapacity, the second highest ranking Sanggunian member shall become the Punong Barangay.\n(c) A tie between or among the highest ranking Sangguniang Panlungsod members shall be resolved by drawing of lots.\n(d) The successors as defined herein shall serve only the unexpired terms of their predecessors.\n(e) For purposes of this Act, a permanent vacancy arises when an elective local official fills in a higher vacant office, refuses to assume office, fails to qualify, dies, is removed from office, voluntarily resigns or is otherwise permanently incapacitated to discharge the functions of his or her office.\n(f) For purposes of succession as provided for in this Act, ranking in the Sanggunian shall be determined on the basis of the proportion of votes obtained by each winning candidate to the total number of registered voters in the City in the immediately preceding local election."}},{"id":"PH-H9531-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Permanent Vacancies in the Sangguniang Panlungsod. – Permanent vacancies in the Sangguniang Panlungsod where automatic succession as provided above does not apply shall be filled in by appointments in the following manner:\n(a) The provincial governor shall make the aforesaid appointments;\n(b) Only the nominee of the political party under which the Sanggunian member concerned had been elected and whose elevation to the position next higher in rank created the last vacancy in the Sanggunian shall be appointed in the manner herein provided. The appointee shall come from the same political party as that of the Sanggunian member who caused the vacancy and shall serve the unexpired term of the vacant office.\nIn the appointment herein mentioned, a nomination and a certificate of membership of the appointee from the highest official of the political party concerned are conditions sine qua non, and any appointment without such nomination and certification shall be null and void ab initio and shall be a ground for administrative action against the official responsible therefor;\n(c) In case the permanent vacancy is caused by a Sanggunian member who does not belong to any political party, the City Mayor shall, upon the recommendation of the Sangguniang Panlungsod, appoint a qualified person to fill in the vacancy; and\n(d) In case of vacancy in the representation of the youth and the barangay in the Sangguniang Panlungsod, said vacancy shall be filled in automatically by the official next-in-rank of the Sangguniang Kabataan or barangay concerned."}},{"id":"PH-H9531-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Temporary Vacancy in the Office of the City Mayor. – (a) When the City Mayor is temporarily incapacitated to perform his or her duties for physical or legal reasons, such as, but not limited to, leave of absence, travel abroad and suspension from office, the City Vice Mayor or the highest ranking Sangguniang Panlungsod member shall automatically exercise the powers and perform the duties and functions of the City Mayor, except the power to appoint, suspend or dismiss employees which can only be exercised if the period of temporary incapacity exceeds thirty (30) working days.\n(b) Said temporary incapacity shall terminate upon submission to the Sangguniang Panlungsod of a written declaration by the City Mayor of having reported back to office. In case where the temporary incapacity is due to a legal cause, the City Mayor shall also submit the necessary documents showing that the said legal cause no longer exists.\n(c) When the City Mayor is traveling within the country but outside the territorial jurisdiction for a period not exceeding three (3) consecutive days, he or she may designate in writing the officer-in-charge of the office. The authorization shall specify the powers and functions that the local official concerned shall exercise in the absence of the City Mayor, except the power to appoint, suspend or dismiss employees.\n(d) In the event, however, that the City Mayor fails or refuses to issue such authorization, the City Vice Mayor or the highest ranking Sangguniang Panlungsod member, as the case may be, shall have the right to assume the powers, duties and functions of the office on the fourth (4th) day of absence of the City Mayor, subject to the limitations provided for in subsection (c) hereof.\n(e) Except as provided above, the City Mayor shall, in no case, authorize any local official to assume the powers, duties and functions of the office other than the City Vice Mayor or the highest ranking member of the Sangguniang Panlungsod, as the case may be.\nTHE APPOINTIVE OFFICIALS OF THE CITY"}},{"id":"PH-H9531-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Secretary to the Sangguniang Panlungsod. – (a) There shall be a secretary to the Sangguniang Panlungsod who shall be a career official with the rank and salary equal to a head of a department or office.\n(b) No person shall be appointed secretary to the Sangguniang Panlungsod unless one is a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in law, commerce or public administration obtained from a recognized college or university and a first grade civil service eligible or its equivalent.\n(c) The secretary to the Sangguniang Panlungsod shall take charge of the office of the Sangguniang Panlungsod , and shall:\n(1) Attend meetings of the Sangguniang Panlungsod and keep a journal of its proceedings;\n(2) Keep the seal of the City and affix it with his or her signature to all ordinances, resolutions and other official acts of the Sangguniang Panlungsod , and present these for the signature of the presiding officer;\n(3) Forward to the City Mayor for approval, copies of ordinances enacted by the Sangguniang Panlungsod, duly certified by the presiding officer in the manner provided in Section 54 of the Local Government Code of 1991, as amended;\n(4) Forward to the Sangguniang Panlalawigan copies of duly approved ordinances in the manner as provided for in Sections 56 and 57 of the Local Government Code of 1991, as amended;\n(5) Furnish, upon the request of any interested party, certified copies of records of public character in one’s custody, upon payment to the City Treasurer of such fees as may be prescribed by ordinance;\n(6) Record in a book kept for the purpose, all ordinances and resolutions enacted or adopted by the Sangguniang Panlungsod , with the dates of passage and publication thereof;\n(7) Keep the office and all nonconfidential records therein open to the public during usual business hours;\n(8) Translate into the dialect used by the majority of the inhabitants, all ordinances and resolutions immediately after their approval, and cause their publication together with the original version in the manner provided under the Local Government Code of 1991, as amended;\n(9) Take custody of the local archives and, where applicable, the local library and annually account for the same; and\n(10) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Treasurer. – (a) The City Treasurer shall be appointed by the Secretary of the Department of Finance (DOF) from a list of at least three (3) ranking eligible recommendees of the City Mayor, subject to civil service law, rules and regulations.\n(b) The City Treasurer shall be under the administrative supervision of the City Mayor, to whom one shall report regularly on the tax collection efforts in the City.\n(c) No person shall be appointed City Treasurer unless one is a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in commerce, public administration or law obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in treasury or accounting service for at least five (5) years.\n(d) The City Treasurer shall have receive compensation, emoluments and allowances as may be determined by law.\n(e) The City Treasurer shall take charge of the City Finance Department, and shall:\n(1) Advise the City Mayor, the Sangguniang Panlungsod and other local government and national officials concerned regarding the disposition of local government funds and on other matters relative to public finance;\n(2) Take custody of and exercise proper management of the funds of the City;\n(3) Take charge of the disbursement of all funds of the City and other funds, the custody of which has been entrusted to him or her by law or other competent authority;\n(4) Inspect private commercial and industrial establishments within the jurisdiction of the City in relation to the implementation of tax ordinances, pursuant to the provisions of the Local Government Code of 1991, as amended;\n(5) Maintain and update the tax information system of the City; and\n(6) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Assessor. – (a) The City Assessor must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce or any other related course obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in real property assessment work or in any related field for at least five (5) years.\n(b) The City Assessor shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Assessor shall take charge of the City Assessor’s Department, and shall:\n(1) Ensure that all laws and policies governing the appraisal and assessment of real properties for taxation purposes are properly executed;\n(2) Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in the valuation and assessment of real properties for taxation purposes;\n(3) Establish a systematic method of real property assessment;\n(4) Install and maintain real property identification and accounting systems;\n(5) Prepare, install, and maintain a system of tax mapping, showing graphically all properties subject to assessment and gather all data concerning the same;\n(6) Conduct frequent physical surveys to verify and determine whether all real properties within the City are properly listed in the assessment rolls;\n(7) Exercise the functions of appraisal and assessment primarily for taxation purposes of all real properties in the City;\n(8) Prepare a schedule of the fair market value of the different classes of real properties in accordance with the provisions of the Local Government Code of 1991, as amended;\n(9) Issue, upon request of any interested party, certified copies of assessment records of real properties and all other records relative to its assessment, upon payment of a service charge or fee to the City Treasurer;\n(10) Submit every semester a report of all assessments, as well as cancellations and modifications of assessments to the City Mayor and the Sangguniang Panlungsod;\n(11) Attend personally or through an authorized representative all sessions of the Local Board of Assessment Appeals whenever his or her assessment is subject of the appeal, and present or submit any information or record in his or her possession as may be required by the Board; and\n(12) Perform other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the \"Local Government Code of 1991\", as amended, and those that are prescribed by law or ordinace."}},{"id":"PH-H9531-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Accountant. - (a) The City Accountant must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a certified public accountant and must have acquired experience in the treasury or accounting service for at least five (5) years.\n(b) The City Accountant shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Accountant shall take charge of both the Office of the Accounting and Internal Audit Services, and shall:\n(1) Install and maintain an internal audit system in the City;\n(2) Prepare and submit financial statements to the City Mayor and to the Sangguniang Panlungsod;\n(3) Apprise the Sangguniang Panlungsod and other officials on the financial condition and operations of the City;\n(4) Certify to the availability of budgetary allotment from which expenditures and obligations may be properly charged;\n(5) Review supporting documents before the preparation of vouchers to determine completeness of requirements;\n(6) Prepare statement of cash advances, liquidations, salaries, allowances, reimbursements and remittances pertaining to the City;\n(7) Prepare statements of journal vouchers, their liquidations, and other adjustments related thereto;\n(8) Post individual disbursements to subsidiary ledgers and index cards;\n(9) Maintain individual ledgers for officials and employees of the City pertaining to payrolls and deductions;\n(10) Record and post in index cards details of purchased furnitures, fixtures and equipment, including disposal thereof, if any;\n(11) Account for all issued requests for obligations and maintain and keep all records and reports related thereto;\n(12) Prepare journals and the analysis of obligations and maintain and keep all records and reports related thereto; and\n(13) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance.\n(d) The incumbent Chief Accountant in the office of the Treasurer shall be given preference in the appointment to the position of Accountant."}},{"id":"PH-H9531-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Budget Officer. – (a) The City Budget Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in accounting, economics, public administration or any related course obtained from a recognized college or university a first grade civil service eligible or its equivalent and must have acquired experience in government budgeting or in any related field for at least five (5) years.\n(b) The City Budget Officer shall take charge of the City Budget Department, and shall:\n(1) Prepare forms, orders and circulars embodying instructions on budgetary and appropriation matters for the signature of the City Mayor;\n(2) Review and consolidate the budget proposals of different departments and offices of the City;\n(3) Assist the City Mayor in the preparation of the budget and during and after the budget hearings;\n(4) Study and evaluate budgetary implications of proposed legislations and submit comments and recommendations thereon;\n(5) Submit periodic budgetary reports to the DBM;\n(6) Coordinate with the City Treasurer, the City Accountant and the City Planning and Development officer for the purpose of budgeting;\n(7) Assist the Sangguniang Panlungsod in reviewing the approved budgets of the component barangays;\n(8) Coordinate with the City Planning and Development Office in the formulation of the development plan of the City; and\n(9) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Planning and Development Officer. – (a) The City Planning and Development Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in urban planning, development studies, economics, public administration, or in any related course obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in development planning or in any related field for at least five (5) years.\n(b) The City Planning and Development Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Planning and Development Officer shall take charge of the City Planning and Development Coordinating Office, and shall:\n(1) Formulate integrated economic, social, physical and other development plans and policies for the consideration of the City;\n(2) Conduct continuing studies, researchers and training programs necessary to evolve plans and programs for implementation;\n(3) Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups or agencies;\n(4) Monitor and evaluate the implementation of the different development programs, projects and activities in the City in accordance with the approved development plan;\n(5) Prepare comprehensive plans and other development planning documents for the consideration of the Local Development Council;\n(6) Analyze the income and expenditure patterns, and formulate and recommend fiscal plans and policies for the consideration of the finance committee of the Sangguniang Panlungsod;\n(7) Promote people’s participation in development planning within the City;\n(8) Exercise supervision and control over the secretariat of the Local Development Council; and\n(9) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Engineer. – (a) The City Engineer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a licensed civil engineer and must have acquired experience in the practice of profession for at least five (5) years.\n(b) The City Engineer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Engineer shall take charge of the City Engineering Office, and shall:\n(1) Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in infrastructure development and public works in general of the City;\n(2) Advise the City Mayor on infrastructure, public works and other engineering matters;\n(3) Administer, coordinate, supervise and control the construction, maintenance, improvement and repair of roads, bridges, other engineering and public works projects of the City;\n(4) Provide engineering services to the City, including investigations and surveys, engineering designs, feasibility studies and project management; and\n(5) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Health Officer. – (a) The City Health Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a licensed medical practitioner and must have acquired experience in the practice of the profession for at least five (5) years.\n(b) The City Health Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Health Officer shall take charge of the Office of the City Health Services, and shall:\n(1) Supervise the personnel and staff of the said office, formulate program implementation guidelines and rules and regulations for the operation of the said office for the approval of the City mayor in order to assist the latter in the efficient, effective and economical implementation of health service programs geared to implement health-related projects and activities;\n(2) Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out activities to ensure the delivery of basic services and the provision of adequate facilities relative to health services as provided for under Section 17 of the Local Government Code of 1991, as amended;\n(3) Develop plans and strategies and, upon approval thereof by the City Mayor, implement these with the health programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide for under the Local Government Code of 1991, as amended;\n(4) In addition to the foregoing duties and functions, the City Health officer shall:\n(i) Formulate and implement policies, plans and projects to promote the health of the people in the City;\n(ii) Advise the City Mayor and the Sangguniang Panlungsod on matters pertaining to health;\n(iii) Execute and enforce all laws, ordinances and regulations relating to public health;\n(iv) Recommend to the Sangguniang Panlungsod through the local health board, the passage of ordinance as may be deemed necessary for the preservation of public health;\n(v) Recommend the prosecution of any violation of sanitary laws, ordinances or regulations;\n(vi) Direct the sanitary inspection of all business establishments, stores selling food items or providing accommodations such as hotels, motels, lodging houses, pension houses and the like, in accordance with the Sanitation Code of the Philippines;\n(vii) Conduct health information campaigns and render health intelligence services;\n(viii) Coordinate with other government agencies and nongovernment organizations involved in the promotion and delivery of health services; and\n(ix) Be in the frontline of the delivery of health services, particularly during and in the aftermath of man-made and natural disasters or calamities; and\n(5) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Civil Registrar. – (a) The City Civil Registrar must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in civil registry work for at least five (5) years.\n(b) The City Civil Registrar shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Civil Registrar shall be responsible for the civil registration program in the City of Sto. Tomas, pursuant to the Civil Registry Law, the Civil Code and other pertinent laws, rules and regulations issued to implement them.\n(d) The City Civil Registrar shall take charge of the Office of the City Civil Registry, and shall:\n(1) Develop plans and strategies and, upon approval thereof by the City Mayor, implement the same, particularly those which have to do with the civil registry programs and projects which the City Mayor is empowered to provide for under the Local Government Code of 1991, as amended;\n(2) In addition to the foregoing duties and functions, the City Civil Registrar shall:\n(i) Accept all registrable documents and judicial decrees affecting the civil status of persons;\n(ii) File, keep and preserve in a secure place the books required by law;\n(iii) Transcribe and enter immediately upon receipt all registrable documents and judicial decrees affecting the civil status of persons in the appropriate civil registry books;\n(iv) Transmit to the Office of the Civil Registrar-General, within the prescribed period, duplicate copies of registered documents required by law;\n(v) Issue certified transcripts or copies of any certificate or registered document upon payment of the required fees to the City Treasurer;\n(vi) Receive application for the issuance of a marriage license and, after determining that the requirements and supporting certificates and publication thereof for the prescribed period have been complied with, issue the license upon payment of the authorized fee to the City Treasurer; and\n(vii) Coordinate with the Philippine Statistics Authority (PSA) in conducting educational campaigns for vital registration and assist in the preparation of demographic and other statistics for the City of Sto. Tomas; and\n(3) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Administrator. – (a) The City Administrator must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in public administration, law or in any other related course from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in management and administrative work for at least five (5) years.\n(b) The term of the City Administrator shall be coterminous with that of the appointing authority.\n(c) The City Administrator shall receive compensation, emoluments and allowances as may be determined by law.\n(d) The City Administrator shall take charge of the City Administrator’s Office, and shall:\n(1) Develop plans and strategies and, upon approval thereof by the City Mayor, implement the same, particularly those which have to do with the management and administration-related programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide for under the Local Government Code of 1991, as amended;\n(2) Assist in the coordination of the work of all the officials of the City, under the supervision, direction and control of the City Mayor and, for this purpose, he or she may convene the chiefs of offices and other officials of the local government unit;\n(3) Establish and maintain a sound personnel program for the local government unit designed to promote career development and uphold the merit principle in the local government service;\n(4) Conduct a continuing organizational development of the local government unit with the end in view of instituting effective administrative reforms;\n(5) Be in the frontline of the delivery of administrative support services, particularly those related to the situations during and in the aftermath of man-made and natural disasters or calamities;\n(6) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all matters relative to the management and administration of the City; and\n(7) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Legal Officer. – (a) The City Legal Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a member of the Philippine bar and must have practiced the profession for at least five (5) years.\nThe term of the City Legal Officer shall be coterminous with that of the appointing authority.\n(b) The City Legal Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Legal Officer, the chief legal counsel of the City, shall take charge of the Office of the City Legal Service, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide legal assistance and support to the City Mayor in carrying out the delivery of basic services and the provision of adequate facilities;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement the same, particularly those which have to do with the programs and projects related to legal services which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Represent the City in all civil actions and special proceedings wherein the local government unit or any official thereof, in his or her official capacity, is a party: Provided, That in actions or proceedings where the City of Sto. Tomas is a party adverse to the provincial government or to another component city, a special legal officer may be employed to represent the adverse party;\n(4) When required by the City Mayor or Sanggunian, draft ordinances, contracts, bonds, leases and other instruments, involving any interest of the local government unit; and provide comments and recommendations on any instruments already drawn;\n(5) Render an opinion in writing on any question of law when requested to do so by the City Mayor or Sanggunian;\n(6) Investigate or cause to be investigated any local official or employee for administrative neglect or misconduct in office, and recommend appropriate action to the City Mayor or Sanggunian, as the case may be;\n(7) Investigate or cause to be investigated any person, firm or corporation holding any franchise or exercising any public privilege for failure to comply with any term or condition in the grant of such franchise or privilege, and recommend appropriate action to the City Mayor or Sanggunian, as the case may be;\n(8) When directed by the City Mayor or Sanggunian, initiate and prosecute in the interest of the local government unit concerned any civil action on any bond, lease or other contract upon any breach or violation thereof;\n(9) Review and submit recommendations on ordinances approved and executive orders issued by component units;\n(10) Recommend measures to the Sangguniang Panlungsod and advise the City Mayor on all matters related to upholding the rule of law;\n(11) Be in the frontline of protecting human rights and prosecuting any violation thereof, particularly those which occur during and in the aftermath of man-made and natural disasters or calamities; and\n(12) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Social Welfare and Development Officer. – (a) The City Social Welfare and Development Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a licensed social worker or a holder of a college degree preferably in social work, sociology or in any other related course obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in the practice of social work for at least five (5) years immediately preceding the date of appointment.\n(b) The City Social Welfare and Development Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Social Welfare and Development Officer shall take charge of the Office of the Social Welfare and Development, and shall:\n(1) Formulate measures for the approval of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to social welfare and development services;\n(2) Develop plans and strategies and, upon approval thereof by the City mayor, implement the same, particularly those which have to do with social welfare programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Identify the basic needs of the needy, the disadvantaged and impoverished and develop and implement appropriate measures to alleviate their problems and improve their living conditions;\n(4) Provide relief and appropriate crisis intervention for victims of abuse and exploitation and recommend appropriate measures to deter further abuse and exploitations;\n(5) Assist the City Mayor in implementing the barangay level program for the total development and protection of children up to six (6) years of age;\n(6) Facilitate the implementation of welfare programs for the disabled, elderly and victims of drug addiction, the rehabilitation of prisoners and parolees, the prevention of juvenile delinquency and such other activities which would eliminate and minimize the ill-effects of poverty;\n(7) Initiate and support youth welfare programs that will enhance the role of the youth in nation building;\n(8) Coordinate with the government agencies and nongovernmental organizations which have for their purpose the promotion and the protection of all the needy, disadvantaged, underprivileged or impoverished groups or individuals, particularly those identified to be vulnerable and high risk to exploitation, abuse and neglect;\n(9) Be in the frontline of the delivery of services particularly those which have to do with the immediate relief and assistance during and in the aftermath of man-made and natural disasters or calamities;\n(10) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all other matters related to social welfare and development services which will improve the livelihood and the living conditions of the City’s inhabitants; and\n(11) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Veterinarian. – (a) The City Veterinarian must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a licensed Doctor of Veterinary Medicine and must have practiced the profession for at least three (3) years.\n(b) The City Veterinarian shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Veterinarian shall take charge of the Office of the Veterinary Services, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement the same, particularly those which have to do with veterinary-related activities which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Advise the City Mayor on all matters pertaining to the slaughter of animals for human consumption and the regulation of slaughterhouses;\n(4) Regulate the keeping of domestic animals;\n(5) Regulate and inspect poultry, milk and dairy products for public consumption;\n(6) Enforce all laws for the prevention of cruelty to animals;\n(7) Take the necessary measures to eradicate, prevent or cure all forms of animal diseases;\n(8) Be in the frontline of veterinary-related activities, including the outbreak of highly contagious and deadly diseases, and in situations resulting in the depletion of animals for work and for human consumption, particularly those arising from and in the aftermath of man-made and natural disasters or calamities;\n(9) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all other matters relative to the veterinary services which will increase the number and improve the quality of livestock, poultry and other domestic animals used for work or for human consumption; and\n(10) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City General Services Officer. – (a) The City General Services Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree in public administration, business administration or management obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in general services, including the management of supply, property, solid waste disposal and general sanitation for at least five (5) years.\n(b) The City General Services Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City General Services Officer shall take charge of the Office of the General Services, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities which require general services expertise in technical support services;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement these with general services that are supportive of the welfare of the inhabitants of the City which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Take custody of and be accountable for all properties, real or personal, owned by the City and those granted to it in the form of donation, reparation, assistance and counterpart of joint projects;\n(4) With the approval of the City Mayor, assign building or land space to local officials or other public officials, who by law are entitled to the space;\n(5) Recommend to the City Mayor reasonable rental rates for local government properties, whether real or personal, which will be leased to public or private entities by the local government;\n(6) Maintain and supervise janitorial, security, landscaping and other related services in all local government public buildings and other real property, whether owned or leased by the local government unit;\n(7) Collate and disseminate information regarding prices, shipping and other costs of supplies and other items commonly used by the local government unit;\n(8) Perform archival and record management with respect to records of offices and departments of the local government unit;\n(9) Perform all other functions pertaining to supply and property management heretofore performed by the local government treasurer and enforce policies on records creation, maintenance and disposal;\n(10) Be in the frontline of general services-related activities, including the possible and imminent destruction or damage to records, supplies, properties and structure and the orderly and sanitary clearing up of waste materials or debris, particularly during and in the aftermath of man-made and natural disasters or calamities;\n(11) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all matters relative to general services; and\n(12) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Environment and Natural Resources Officer. – (a) The City Environment and Natural Resources Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in environment, forestry, agriculture or in any other related course obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in environment and natural resources management, conservation and utilization work for at least five (5) years.\n(b) The City Environment and Natural Resources Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Environment and Natural Resources Officer shall take charge of the City Environment Service Department, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to environment and natural resources services as provided for under Section 17 of the Local Government Code of 1991, as amended;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement these with the environment and natural resources programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Establish, maintain, protect and preserve communal forests, watersheds, tree parks, mangroves, greenbelts and similar forest projects and commercial forests, like industrial tree farms and agro-forestry projects;\n(4) Provide extension services to beneficiaries of forest development projects and technical, financial and infrastructure assistance;\n(5) Manage and maintain seed banks and produce seedlings for forest and tree parks;\n(6) Provide extension services to beneficiaries of forest development projects and render assistance for natural resources-related conservation and utilization activities consistent with ecological balance;\n(7) Coordinate with government agencies and nongovernmental organizations in the implementation of measures to prevent and control land, air and water pollution with the assistance of the Department of Environment and Natural Resources (DENR);\n(8) Be in the frontline of the delivery of services concerning the environment and natural resources, particularly in the renewal and rehabilitation of the environment during and in the aftermath of man-made and natural disasters or calamities;\n(9) Recommend measures to the Sangguniang Panlungsod and advise the City Mayor on all matters relative to the protection, conservation, maximum utilization, application of appropriate technology and other matters related to the environment and natural resources; and\n(10) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Architect. – (a) The City Architect must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a duly licensed architect and must have practiced the profession for at least five (5) years.\n(b) The City Architect shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Architect shall take charge of the office of the Architectural Planning and Design, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to architectural planning and design;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement these with architectural planning and design programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Prepare and recommend for consideration of the Sanggunian the architectural plan and design for the local government unit or a part thereof, including the renewal of slums and blighted areas, land reclamation activities, the greening of land and appropriate planning of marine and foreshore areas;\n(4) Review and recommend for appropriate action of the Sanggunian or the City Mayor, as the case may be, the architectural plans and designs submitted by governmental and nongovernmental entities or individuals, particularly those for undeveloped and poorly designed areas;\n(5) Coordinate with government and nongovernment entities and individuals involved in the aesthetics and maximum utilization of the land and water within the jurisdiction of the local government unit to implement plans and programs that shall preserve environmental integrity and ecological balance;\n(6) Be in the frontline of the delivery of services involving architectural planning and design, particularly those related to the redesigning of spatial distribution of basic facilities and physical structures during and in the aftermath of man-made and natural disasters or calamities;\n(7) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all other matters relative to architectural planning and design as it relates to the total socioeconomic development of the City; and\n(8) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Information Officer. – (a) The City Information Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in journalism, mass communication or in any related course obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have experience in writing articles and research papers, or writing for print, television or broadcast media for at least three (3) years.\n(b) The City Information Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The term of the City Information Officer is coterminous with that of his or her appointing authority.\n(d) The City Information Officer shall take charge of the City Information and Community Relations Department, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in providing the information and research data required for the delivery of basic services and the provision of adequate facilities so that the public becomes aware of said services and may fully avail of the same;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement the same, particularly those which have to do with public information and research data to support programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Provide relevant, adequate and timely information to the local government unit and its residents;\n(4) Furnish information and data on local government agencies or offices as may be required by law or ordinance; and nongovernmental organization to be furnished by said agencies and organizations;\n(5) Maintain effective liaison with the various sectors of the community on matters and issues that affect the livelihood and the quality of life of the City’s inhabitants and encourage support for programs of the local and national government;\n(6) Be in the frontline in providing information during and in the aftermath of man-made and natural disasters or calamities, with special attention to the victims thereof, to help minimize injuries and casualties during and after the emergency, and to accelerate relief and rehabilitation;\n(7) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all other matters relative to public information and research data as it related to the total socioeconomic development of the City; and\n(8) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Cooperatives Officer. – (a) The City Cooperatives Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in business administration with special training on cooperatives or in any related course obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in cooperatives organization and management for at least five (5) years.\n(b) The City Cooperatives Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Cooperatives Officer shall take charge of the Office for the Development of Cooperatives, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of facilities through the development of cooperatives and in providing access to such services and facilities;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement these with the integration of cooperatives principles and methods in programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Assist in the organization of cooperatives;\n(4) Provide technical and other forms of assistance to existing cooperatives to enhance their viability as an economic enterprise and social organization;\n(5) Assist cooperatives in establishing linkages with government agencies and nongovernmental organizations involved in the promotion and integration of the concept of cooperatives in the livelihood of the people and other community activities;\n(6) Be in the frontline of cooperatives organization, rehabilitation or viability enhancement, particularly during and in the aftermath of man-made and natural disasters or calamities, to aid in their survival and, if necessary, subsequent rehabilitation;\n(7) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all other matters relative to cooperatives development and viability enhancement which will improve the livelihood and the quality of life of the inhabitants; and\n(8) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Population Officer. – (a) The City Population Officer must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably with specialized training in population development obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have acquired experience in the implementation of programs on population development or responsible parenthood for at least five (5) years.\n(b) The City Population Officer shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Population Officer shall take charge of the Office of the Population Development, and shall:\n(1) Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to the integration of the population development principles and in providing access to said services and facilities;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement these with the integration of population development principles and methods in programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) Assist the City Mayor in the implementation of the constitutional provisions relative to population development and the promotion of responsible parenthood;\n(4) Establish and maintain an updated data bank for program operations, development planning and an educational program to ensure the people’s participation in, and understanding of, population development;\n(5) Implement appropriate training programs responsive to the cultural heritage of the inhabitants; and\n(6) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance."}},{"id":"PH-H9531-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Agriculturist. – (a) The City Agriculturist must be a citizen of the Philippines, a resident of the City of Sto. Tomas, of good moral character, a holder of a college degree preferably in agriculture or in any other related course obtained from a recognized college or university, a first grade civil service eligible or its equivalent and must have practiced the profession in agriculture or acquired experience in s related field for at least five (5) years.\n(b) The City Agriculturist shall receive compensation, emoluments and allowances as may be determined by law.\n(c) The City Agriculturist shall take charge of the Office of the Agriculture Services, and shall:\n(1) Formulate measures for the approval of the Sangguniang Panlungsod and provide technical assistance and support to the City Mayor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to agricultural services;\n(2) Develop plans and strategies and, upon approval thereof by the City Mayor, implement the same, particularly those which have to do with the agricultural programs and projects which the City Mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n(3) In addition to the foregoing duties and functions, the City Agriculturist shall:\n(i) Ensure that maximum assistance and access to resources in the production, processing and marketing of agricultural, aquacultural and marine products are extended to farmers, fishermen and local entrepreneurs;\n(ii) Conduct or cause to be conducted location-specific agricultural researchers and assist in making available the appropriate technology arising out of and disseminating information on basic research on crops, prevention and control of plant diseases and pests, and other agricultural matters which will maximize productivity;\n(iii) Assist the City Mayor in the establishment and extension services of demonstration farms on aquaculture and marine products;\n(iv) Enforce rules and regulations relating to agriculture and aquaculture; and\n(v) Coordinate with government agencies and nongovernmental organizations in the promotion of agricultural productivity through applied technology compatible with environment integrity;\n(4) Be in the frontline of the delivery of basic agricultural services, particularly those needed for the survival of the City’s inhabitants during and in the aftermath of man-made and natural disasters or calamities;\n(5) Recommend to the Sangguniang Panlungsod and advise the City Mayor on all other matters related to agriculture and aquaculture which will improve the livelihood and the living conditions of the inhabitants; and\n(6) Perform other duties and functions and exercise such other powers as provided for under the Local Government Code of 1991, as amended, and those that are prescribed by law or ordinance.\nTHE CITY FIRE STATION SERVICE, THE CITY JAIL SERVICE,\nTHE CITY SCHOOLS DIVISION AND THE CITY PROSECUTION SERVICE"}},{"id":"PH-H9531-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The City Fire Station Service. – (a) There shall be established in the City at least one (1) fire station with adequate personnel, firefighting facilities and equipment, subject to the standards, rules and regulations that may be promulgated by the Department of the Interior and Local Government (DILG). The City shall provide the necessary land or site of the station.\n(b) The city fire station shall be headed by a City Fire Marshal whose qualifications shall be as those provided for under Republic Act No. 9263, as amended, otherwise known as the \"Bureau of Fire Protection and Bureau of Jail Management and Penology Professionalization Act of 2004\".\n(c) The city fire station shall be responsible for providing emergency services, including the rescue and evacuation of injured people related to incidents and, in general, all fire prevention and suppression measures to secure the safety of life and property of the citizenry."}},{"id":"PH-H9531-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The City Jail Service. – (a) There shall be established and maintained in the City a secure, clean, adequately equipped and sanitary jail for the custody and safekeeping of prisoners, any fugitive from justice, or person detained awaiting investigation or transfer to the National Penitentiary, and/or trial and/or violent mentally ill person who endangers oneself or the safety of others, duly certified as such by the proper medical health officer, pending the transfer to a mental institution.\n(b) The city jail service shall be headed by a City Jail Warden whose qualifications shall be as those provided for under the Bureau of Fire Protection and Bureau of Jail Management and Penology Professionalization Act of 2004. One shall assist in the immediate rehabilitation of individuals or detention prisoners. The City Jail Warden shall ensure that great care is exercised at all times so that the human rights of prisoners are respected and protected, and their spiritual and physical well-being are properly and promptly attended to."}},{"id":"PH-H9531-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The City Schools Division. – (a) There shall be established and maintained by the Department of Education (DepEd), a city schools division of the City of Sto. Tomas whose area of jurisdiction will cover all the school districts within the City.\n(b) The city schools division shall be headed by a City Schools Division Superintendent who must possess the necessary qualifications required by the DepEd."}},{"id":"PH-H9531-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The City Prosecution Service. – (a) There shall be established in the City, a city prosecution service to be headed by a City Prosecutor and such number of assistant city prosecutors, as may be necessary, who shall be organizationally part of the Department of Justice (DOJ), and under the supervision and control of the Secretary of Justice and whose qualifications, manner of appointment, rank, salary and benefits shall be governed by existing laws covering prosecutors in the DOJ.\n(b) The City Prosecutor shall handle the criminal prosecution in the municipal trial courts in the City as well as in the regional trial courts for criminal cases originating in the territory of the City, and shall render to or for the City such services as are required by law, ordinance or regulation of the DOJ.\nThe Secretary of Justice shall always ensure the adequacy and the quality of prosecution service in the City and, for this purpose, shall, in the absence, lack or insufficiency in number of assistant city prosecutors as provided hereinabove, designate from among the assistant provincial prosecutors a sufficient number to perform and discharge the functions of the city prosecution service as provided hereinabove.\nTRANSITORY AND FINAL PROVISIONS"}},{"id":"PH-H9531-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Municipal Ordinances Existing at the Time of the Approval of this Act. – All municipal ordinances of the Municipality of Sto. Tomas existing at the time of the approval of this Act shall continue to be in force within the City of Sto. Tomas until the Sangguniang Panlungsod shall declare otherwise."}},{"id":"PH-H9531-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Plebiscite. – The City of Sto. Tomas shall acquire corporate existence upon the ratification of its creation by a majority of the votes cast by the qualified voters in a plebiscite to be conducted in the present Municipality of Sto. Tomas within ninety (90) days from the approval of this Act.\nThe Commission on Elections shall conduct and supervise such plebiscite.\nThe expenses for the plebiscite shall be borne by the Municipality of Sto. Tomas."}},{"id":"PH-H9531-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Officials of the City of Sto. Tomas. – The present elective officials of the Municipality of Sto. Tomas shall continue to exercise their powers and functions until such time that a new election is held and the duly elected officials shall have already qualified and assumed their offices. The two (2) additional members of the Sangguniang Panlungsod shall be appointed by the City Mayor and shall assume office until such time that the regular members of the Sangguniang Panlungsod have been elected and qualified in the next national and local elections after the effectivity of this Act. Appointive officials and employees of the municipality shall likewise continue exercising their functions and duties and they shall be automatically absorbed by the city government of the City of Sto. Tomas."}},{"id":"PH-H9531-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Succession Clause. – The City of Sto. Tomas shall succeed to all the assets, properties, liabilities and obligations of the Municiaplity of Sto. Tomas."}},{"id":"PH-H9531-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Election of Provincial Governor and Sangguniang Panlalawigan Members of the Province of Batangas. – The qualified voters of the City of Sto. Tomas shall be qualified to vote and run for any elective position in the elections for provincial governor, provincial vice governor, Sangguniang Panlalawigan members and other elective officials for the Province of Batangas."}},{"id":"PH-H9531-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Jurisdiction of the Province of Batangas. - The City of Sto. Tomas shall, unless otherwise provided by law, continue to be under the jurisdiction of the Province of Batangas."}},{"id":"PH-H9531-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Suspension of Increase in Rates of Local Taxes. – No increase in the rates of local taxes shall be imposed by the City within the period of five (5) years from its acquisition of corporate existence."}},{"id":"PH-H9531-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Legislative District. – Until otherwise provided by law, the City of Sto. Tomas shall continue to be a part of the Third Legislative District of the Province of Batangas."}},{"id":"PH-H9531-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Applicability of Laws. – The provisions of the Local Government Code of 1991, as amended, and other laws pertaining to the Province of Batangas and such laws as are applicable shall govern the City of Sto. Tomas insofar as they are not inconsistent with the provisions of this Act."}},{"id":"PH-H9531-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Separability Clause. – If, for any reason or reasons, any part or provision of this Charter shall be held unconstitutional, invalid or inconsistent with the Local Government Code of 1991, as amended, the other parts or provisions hereof which are not affected shall continue to be in full force and effect."}},{"id":"PH-H9531-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p135"};
  FT["PH-H9532"] = {"id":"PH-H9532","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11087_2018.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将三宝颜市三宝颜市医疗中心床位由五百（500）张增至八百（800）张并为其拨款，为此修订经修正的第 7272 号共和国法","en":"An Act Increasing the Bed Capacity of the Zamboanga City Medical Center in Zamboanga City From Five Hundred (500) to Eight Hundred (800) Beds and Appropriating Funds Therefor Amending for the Purpose Republic Act No. 7272, as Amended, Entitled \"An Act Converting the Zamboanga Regional Hospital in Zamboanga City Into Zamboanga City Medical Center, and Appropriating Funds Therefor\"","orig":"An Act Increasing the Bed Capacity of the Zamboanga City Medical Center in Zamboanga City From Five Hundred (500) to Eight Hundred (800) Beds and Appropriating Funds Therefor Amending for the Purpose Republic Act No. 7272, as Amended, Entitled \"An Act Converting the Zamboanga Regional Hospital in Zamboanga City Into Zamboanga City Medical Center, and Appropriating Funds Therefor\""},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 11087","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-10","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11087_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9532-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The authorized bed capacity of the Zamboanga City Medical Center in Zamboanga City is hereby increased from five hundred (500) to eight hundred (800) beds."}},{"id":"PH-H9532-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The existing hospital facilities and professional health care services of the Zamboanga City Medical Center are hereby upgraded to conform with and be commensurate to the increase in its bed capacity as provided in Section 1 hereof."}},{"id":"PH-H9532-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The existing workforce of the Zamboanga City Medical Center shall also be correspondingly increased. The Department of Health, shall, in coordination with the Department of Budget and Management and the Civil Service Commission, and after consultation with the Zamboanga City Medical Center, determine the additional plantilla positions to be created pursuant to this Act."}},{"id":"PH-H9532-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The increase in bed capacity of the Zamboanga City Medical Center from five hundred (500) to eight hundred (800) beds shall be implemented for a period of not more than two (2) years from the approval of this Act."}},{"id":"PH-H9532-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Health shall immediately include in the Department's programs the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9532-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Zamboanga City Medical Center in Zamboanga City From Five Hundred (500) to Eight Hundred (800) Beds and Appropriating Funds Therefor Amending for the Purpose Republic Act No. 7272, as Amended, Entitled \"An Act Converting the Zamboanga Regional Hospital in Zamboanga City Into Zamboanga City Medical Center, and Appropriating Funds Therefor\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9533"] = {"id":"PH-H9533","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11088_2018.html","fetchedAt":"2026-10-06","articleCount":26,"structureMode":"ARTICLE","title":{"zh":"将 Sorsogon 省 Sorsogon 国立学院改设为国立大学，名称为 Sorsogon 国立大学，并为此拨款的法案","en":"An Act Converting the Sorsogon State College in the Province of Sorsogon Into a State University to Be Known as the Sorsogon State University and Appropriating Funds Therefor","orig":"An Act Converting the Sorsogon State College in the Province of Sorsogon Into a State University to Be Known as the Sorsogon State University and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 11088","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-11","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11088_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 26 条，缺 7、8、9、10、11、14、16、20、24、25）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9533-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Conversion. The Sorsogon State College (SSC) in the Province of Sorsogon, which is composed of the SSC-Sorsogon Campus i"},"text":{"en":"Section 1. Conversion. The Sorsogon State College (SSC) in the Province of Sorsogon, which is composed of the SSC-Sorsogon Campus in Sorsogon City, the SSC-Bulan Campus in the Municipality of Bulan, the SSC-Magallanes Campus in the Municipality of Magallanes, and the SSC-Castilla Campus in the Municipality of Castilla, all located in the Province of Sorsogon, is hereby converted into a state university to be known as the Sorsogon State University. The main campus of the University shall be in Sorsogon City."}},{"id":"PH-H9533-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"General Mandate. - The Sorsogon State University, hereinafter referred to as the University, shall primarily provide adv"},"text":{"en":"Section 2. General Mandate. - The Sorsogon State University, hereinafter referred to as the University, shall primarily provide advance and higher professional, technical and special instructions in education and technology, engineering and architecture, public administration and management, accountancy, economics and finance, agriculture, forestry and fisheries, arts and sciences, maritime education, peace and security courses and other related fields of study. It shall also undertake research and extension, as well as income generation programs, for the sustainable development of the Province of Sorsogon and Region V."}},{"id":"PH-H9533-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"Curricular Offerings. - The University shall offer undergraduate and graduate courses in the fields of education and tec"},"text":{"en":"Section 3. Curricular Offerings. - The University shall offer undergraduate and graduate courses in the fields of education and technology, engineering and architecture, public administration and management, accountancy, economics and finance, agriculture, forestry and fisheries, arts and sciences, maritime education, peace and security courses, information technology and other courses within its areas of specialization and according to its capabilities as the Board of Regents may deem necessary to carry out its objectives, particularly in meeting the needs of the Province of Sorsogon and Region V.\nThe existing reasonably-sized laboratory high school shall continue to operate under the control of the College of Education of the University to serve the in-campus requirements of the students in the College of Education."}},{"id":"PH-H9533-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"Administration. - The University shall have the general powers of a corporation set forth in Batas Pambansa Blg. 68, as"},"text":{"en":"Section 4. Administration. - The University shall have the general powers of a corporation set forth in Batas Pambansa Blg. 68, as amended, otherwise known as \"The Corporation Code of the Philippines.\" The administration of the University and the exercise of its corporate powers shall be vested exclusively in the Board of Regents and the President of the University."}},{"id":"PH-H9533-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"The Governing Board. – The governing board of the University shall be the Board of Regents, hereinafter referred to as t"},"text":{"en":"Section 5. The Governing Board. – The governing board of the University shall be the Board of Regents, hereinafter referred to as the Board, which shall be chaired and co-chaired by the Chairperson of the Commission on Higher Education (CHED) and President of the University, respectively, with the following as members:\n(a) The Chairperson of the Committee on Education, Arts and Culture of the Senate;\n(b) The Chairperson of the Committee on Higher and Technical Education of the House of Representatives; (c) The Regional Director of the National Economic and Development Authority (NEDA);\n(d) The Regional Director of the Department of Science and Technology (DOST);\n(e) The Regional Director of the Department of Agriculture (DA);\n(f) The President of the Federation of Faculty Associations of the University;\n(g) The President of the Federation of Student Councils of the University;\n(h) The President of the Federation of Alumni Associations of the University; and\n(i) Two (2) prominent citizens from the private sector who have distinguished themselves in their professions or fields of specialization of the University.\nThe Board shall appoint the two (2) prominent citizens from among a list of at least five (5) qualified persons from the Province of Sorsogon, as recommended by the search committee to be constituted by the University President, in consultation with the CHED Chairperson and the other members of the Board, based on the standards and qualifications for the position set by the Board. They shall serve for a term of two (2) years from the date of appointment.\nThe term of the President of the Federation of Faculty Associations, the President of the Federation of Alumni Associations, and the President of the Federation of Student Councils, as members of the Board, shall be coterminous with their terms of office as set forth in their respective Constitution and bylaws."}},{"id":"PH-H9533-A6","no":6,"noLabel":{"en":"Section 6."},"heading":{"en":"Powers and Duties of the Board. - The Board, in addition to its general powers of administration and the exercise of all"},"text":{"en":"Section 6. Powers and Duties of the Board. - The Board, in addition to its general powers of administration and the exercise of all the powers granted to the Board of Directors of a corporation under existing laws, shall have the following specific powers and duties:\n(a) To promulgate and implement policies in accordance with the declared state policies on education and other pertinent provisions of the Philippine Constitution on education, agriculture, science and technology, as well as the policies, standards and thrusts of the CHED under Republic Act No. 7722, otherwise known as the \"Higher Education Act of 1994\";\n(b) To approve the curricula, instructional programs, and rules of discipline drawn by the Administrative and the Academic Councils herein provided;\n(c) To appoint, upon the recommendation of the President of the University, the vice presidents, deans, directors, heads of the campuses, faculty members and other officials and employees of the University;\n(d) To fix and adjust salaries of faculty members, administrative officials and employees, subject to the provisions of the Revised Compensation and Position Classification System and other pertinent budget and compensation laws governing hours of service and such other duties and conditions as it may deem proper; to grant them, at its discretion, leaves of absence under such regulations as it may promulgate, any provision of existing law to the contrary notwithstanding; and to remove them for cause in accordance with the requirements of due process of law;\n(e) To fix the tuition fees and other necessary school charges, such as matriculation fees, graduation fees and laboratory fees, as the Board may deem proper to impose, after due consultation with the involved sectors. The fees and charges, including government subsidies and other income generated by the University, shall constitute a special trust fund, and shall be deposited in any authorized government depository bank, and all interests that shall accrue therefrom shall form part of the same funds for the use of the University. Any provision of existing law, rule or regulation to the contrary notwithstanding, any income generated by the University from tuition fees and other charges, as well as from the operation of auxiliary services, and land grants, shall be retained by the University, and may be disbursed by the Board for instruction, research, extension or other programs/projects of the University: Provided, That all fiduciary fees shall be disbursed for the specific purposes for which these are collected. If, for reasons beyond its control, the University shall not be able to pursue any project for which the funds have been appropriated and allocated under its approved program of expenditures, the Board may authorize the use of said funds for any reasonable purpose which, in its discretion, may be necessary and urgent for the attainment of the objectives and goals of the University;\n(f) To receive and appropriate all sums as may be provided for the support of the University in the manner it may determine, in its discretion, to carry out the purposes and functions of the University;\n(g) To adopt and implement a socialized scheme of tuition and other school fees for greater access of poor but deserving students;\n(h) To set the policies on admission and graduation of students;\n(i) To establish professorial chairs in the University and to provide fellowships for qualified faculty members, and scholarships to deserving students;\n(j) To award honorary degrees upon persons in recognition of their outstanding contribution in the fields of education, public service, arts, science and technology, agriculture or any field of specialization within the academic competence of the University, and to authorize the awarding of certificates of completion of nondegree and nontraditional courses;\n(k) To establish research and extension centers to promote the development of the University;\n(l) To establish and absorb non-chartered tertiary institutions within the Province of Sorsogon as branches and extension centers in coordination with the CHED and in consultation with the Department of Budget and Management (DBM), and to offer therein programs or courses to carry out the constitutional mandate of providing equal access to educational opportunities;\n(m) To develop academic arrangements for institution capability building with appropriate institutions and agencies, public and private and local and foreign, and to appoint experts/ specialists as consultants, part-time, visiting or exchange professors, scholars, researchers, as the case may be;\n(n) To set up the adoption of modern and innovative modes of transmitting knowledge such as the use of information technology, the dual training system, open distance learning, and community laboratory for the promotion of greater access to education;\n(o) To authorize an external management audit of the University, to be financed by the CHED, subject to the rules and regulations of the Commission on Audit (COA); and to institute reforms, including academic and structural changes, on the basis of the audit results and recommendations;\n(p) To collaborate with the governing boards of the state universities and colleges (SUCs) within the Province of Sorsogon, under the supervision of the CHED and in consultation with the DBM, and work towards restructuring of the University to become more efficient, relevant, productive and competitive;\n(q) To develop consortia and other economic forms of linkages with local government units (LGUS), institutions and agencies, both public and private and local and foreign, in the furtherance of the purpose and objectives of the University;\n(r) To enter into joint ventures with business and industry for the profitable development and management of the economic assets of the University, the proceeds from which shall be used for the development and strengthening of the University;\n(s) To import economic, technical and cultural books and publications;\n(t) To receive in trust legacies, gifts and donations of real and personal properties of all kinds and to administer and dispose of the same when necessary for the benefit of the University and subject to the limitations, directions and instructions of the donor, if any;\n(u) To authorize the construction or repair of its buildings, machinery, equipment and other facilities, and the purchase and acquisition of real property, including necessary supplies, materials and equipment;\n(v) To extend the term of the President of the University beyond the age of retirement, but not beyond the age of seventy (70) based on the guidelines, qualifications and standards act of the Board: Provided, That the President's performance has been rated by the Board as outstanding, and after unanimous recommendation by the search committee;\n(w) To establish policy guidelines and procedures for participative decision-making and transparency within the University;\n(x) To privatize, where most advantageous to the University, the management of nonacademic services such as health, food, building or grounds or property maintenance, and such other similar activities;\n(y) To delegate any of its powers and duties provided to the President and other officials of the University, as it may deem appropriate, so as to expedite the administration of the affairs of the University; and\n(z) To promulgate rules and regulations as may be necessary to carry out the purposes and functions of the University.1âwphi1"}},{"id":"PH-H9533-A7","no":7,"noLabel":{"en":"Section 7."},"heading":{"en":"Meetings of the Board. - The Board shall regularly convene once every quarter. However, the Chairperson of the Board may"},"text":{"en":"Section 7. Meetings of the Board. - The Board shall regularly convene once every quarter. However, the Chairperson of the Board may, upon three (3) days prior written notice, call a maximum of two (2) special meetings whenever necessary within the year.\nA quorum of the Board shall consist of majority of all its members holding office at the time of the meeting: Provided, however, That the Chairperson of the Board or the President of the University is among those present in the meeting.\nIn the absence of the CHED Chairperson, a Commissioner of the CHED, duly designated by the CHED Chairperson, as representative in the meeting, shall have all the rights and responsibilities of a regular member: Provided, however, That during this meeting, the President of the University, as Vice Chairperson, shall be the Presiding Officer: Provided, further, That this proviso, notwithstanding, the Chairperson of the CHED is hereby authorized to designate a CHED Commissioner as the regular Chairperson of the Board, in which case said CHED Commissioner, shall act as the Presiding Officer.\nIn case the Chairpersons of the Congressional Committees on Education, Arts and Culture and the House Committee on Higher and Technical Education will not be able to attend the Board meeting, they may designate their respective representatives to attend the meeting, who will have the same rights and responsibilities as regular members of the Board.\nThe members of the Board shall not receive any salary, but shall be entitled to reimbursements for actual and necessary expenses incurred, either for their attendance in the meetings of the Board or in connection with other official business authorized by resolution of the Board, subject to existing laws and regulations."}},{"id":"PH-H9533-A8","no":8,"noLabel":{"en":"Section 8."},"heading":{"en":"The University President. - The University shall be headed by a President, who shall render full-time service and who sh"},"text":{"en":"Section 8. The University President. - The University shall be headed by a President, who shall render full-time service and who shall be appointed by the Board, upon recommendations of a duly constituted search committee. The President shall serve a term of four (4) years and shall be eligible for reappointment for another term: Provided, That in order to effect the smooth transition of the Sorsogon State College to a state university, the incumbent President of the Sorsogon State College, if qualified, shall serve as the first President of the University.\nWithin six (6) months before the expiration of the term of office of the incumbent President of the University, the Board shall constitute the Search Committee for the Presidency (SCP).\nThe Board shall designate an Officer-in-Charge (OIC) of the University in case of vacancy in the Office of the President by reason of death, compulsory retirement, resignation, removal for cause, or incapacity of the President to perform the functions of the office, pending the appointment of a new President: Provided, That the OIC shall serve only the unexpired portion of the term.\nThe powers and duties of the President of the University, in addition to those provided in this Act, shall be those usually pertaining to the Office of the President of similar universities, and those delegated by the Board.\nThe salary of the President of the University shall be in accordance with the Revised Compensation and Position Classification System, as modified by Joint Resolution No. 4 dated June 17, 2009, and by such other laws amendatory thereto, which may hereinafter be enacted, and shall be comparable to that being received by the Presidents of similar educational institutions.\nThe President of the University shall be assisted by a Vice-President for Academic Affairs, a Vice-President for Finance and Administration, and a Vice-President for Research, Extension and Training, who shall be appointed by the Board upon recommendation of the President."}},{"id":"PH-H9533-A9","no":9,"noLabel":{"en":"Section 9."},"heading":{"en":"Heads of University Campuses. – The Campus Directors shall serve as heads or administrators of the University campuses a"},"text":{"en":"Section 9. Heads of University Campuses. – The Campus Directors shall serve as heads or administrators of the University campuses and shall render full-time service.\nThey shall be appointed/designated by the Board upon recommendation of the Search Committee and the President, subject to the guidelines, qualifications and standards set by the Board: Provided, That the incumbent Campus Directors of the existing campuses shall serve as Campus Directors of their respective campuses upon the effectivity of this Act."}},{"id":"PH-H9533-A10","no":10,"noLabel":{"en":"Section 10."},"heading":{"en":"The Secretary of the University. - The Board shall appoint a Secretary, who shall serve as such for both the Board and t"},"text":{"en":"Section 10. The Secretary of the University. - The Board shall appoint a Secretary, who shall serve as such for both the Board and the University and who shall keep all records and proceedings of the Board in addition to other duties and responsibilities. The Secretary of the University shall serve upon each member of the Board the appropriate notice of the Board meetings."}},{"id":"PH-H9533-A11","no":11,"noLabel":{"en":"Section 11."},"heading":{"en":"The Treasurer of the University. - The Treasurer of the Philippines shall be the ex officio treasurer of the University."},"text":{"en":"Section 11. The Treasurer of the University. - The Treasurer of the Philippines shall be the ex officio treasurer of the University."}},{"id":"PH-H9533-A12","no":12,"noLabel":{"en":"Section 12."},"heading":{"en":"Administrative Council. - There shall be an Administrative Council consisting of the President of the University, as Cha"},"text":{"en":"Section 12. Administrative Council. - There shall be an Administrative Council consisting of the President of the University, as Chairperson, and the vice presidents, deans, directors and other officials of equal rank, as members, whose duty is to review and recommend to the Board, policies governing the administration, management and development planning of the University."}},{"id":"PH-H9533-A13","no":13,"noLabel":{"en":"Section 13."},"heading":{"en":"The Academic Council. - There shall be an Academic Council to be composed of the President of the University, who shall"},"text":{"en":"Section 13. The Academic Council. - There shall be an Academic Council to be composed of the President of the University, who shall act as its Chairperson, and all academic staff with the rank of at least an assistant professor, as members.\nThe Academic Council shall have the power to review and recommend the curricular offerings and rules of discipline of the University, subject to the approval of the Board. It shall fix the requirements for the admission of students, as well as for their graduation and conferment of degrees, subject to the review and approval of the Board through the President of the University.\nIt shall have disciplinary power over the students of the University and shall formulate academic policies, rules and regulations on discipline, subject to the approval of the Board."}},{"id":"PH-H9533-A14","no":14,"noLabel":{"en":"Section 14."},"heading":{"en":"The Faculty. - No political belief, gender preference, cultural or community affiliation, ethnic origin, and religious o"},"text":{"en":"Section 14. The Faculty. - No political belief, gender preference, cultural or community affiliation, ethnic origin, and religious opinion or affiliation shall be a matter of inquiry in the appointment of faculty members of the University: Provided, That the appointment shall be subject to the guidelines, qualifications and standards set by the Board: Provided, further, That a member of the faculty shall not criticize, vouch for, recruit members in behalf of, or preach about any particular church or religious sect."}},{"id":"PH-H9533-A15","no":15,"noLabel":{"en":"Section 15."},"heading":{"en":"Scholarship Program / Admission. - The University shall provide a scholarship program and other affirmative action progr"},"text":{"en":"Section 15. Scholarship Program / Admission. - The University shall provide a scholarship program and other affirmative action programs to assist poor but deserving students who qualify for admission to the University. No student shall be denied admission to the University by reason of sex, religion, political, cultural or community affiliation, and ethnic origin."}},{"id":"PH-H9533-A16","no":16,"noLabel":{"en":"Section 16."},"heading":{"en":"Authority to Loan or Transfer Apparatus/ Equipment/Supplies and Detail of Personnel. - The heads of the bureaus and offi"},"text":{"en":"Section 16. Authority to Loan or Transfer Apparatus/ Equipment/Supplies and Detail of Personnel. - The heads of the bureaus and offices of the national government are hereby authorized to loan or transfer, upon the request of the President of the University, such apparatus, equipment or supplies as may be needed by the University, and to detail employees for duty therein when, in the judgment of the head of bureau or office, such apparatus, equipment, supplies or services of such employees can be spared without serious detriment to public service. The employees so detailed shall perform such duties as required of them by the President of the University, and the time so employed shall be counted as part of their regular services."}},{"id":"PH-H9533-A17","no":17,"noLabel":{"en":"Section 17."},"heading":{"en":"Assets, Liabilities and Personnel. - All assets, real and personal, personnel and records of the SSC, as well as liabili"},"text":{"en":"Section 17. Assets, Liabilities and Personnel. - All assets, real and personal, personnel and records of the SSC, as well as liabilities or obligations, are hereby transferred to the University: Provided, That the positions, rights and security of tenure of the faculty members and personnel therein employed under existing laws prior to the conversion into a University shall be respected: Provided, further, That the incumbents of the positions shall remain in the same status until otherwise provided for by the Board: Provided, finally, That the University shall also include an upgrade or increase in its human resource component.\nAll parcels of land belonging to the government occupied by the SSC are hereby declared to be property of the University, and shall be titled under that name: Provided, That should the University cease to exist or be abolished or should such parcels of land aforementioned be no longer needed by the University, the same shall revert to the concerned LGU or to the Republic of the Philippines, as the case may be."}},{"id":"PH-H9533-A18","no":18,"noLabel":{"en":"Section 18."},"heading":{"en":"Tax Exemption. - The importation of economic, technical and cultural books and publications, which are for economic, tec"},"text":{"en":"Section 18. Tax Exemption. - The importation of economic, technical and cultural books and publications, which are for economic, technical-vocational, scientific, philosophical, historical or cultural purposes made by the University, upon certification by the CHED and TESDA, shall be exempt from customs duties in accordance with the provisions 12 of Republic Act No. 10863, otherwise known as the \"Customs Modernization and Tariff Act.\""}},{"id":"PH-H9533-A19","no":19,"noLabel":{"en":"Section 19."},"heading":{"en":"Development Plan, Management Audit, Organization / Administrative/Academic Structure. – Within the period of one hundred"},"text":{"en":"Section 19. Development Plan, Management Audit, Organization / Administrative/Academic Structure. – Within the period of one hundred twenty (120) days after the approval of this Act, the University shall accomplish the following:\n(a) Submit a five (5)-year development plan, including corresponding program budget to the CHED, for corresponding recommendation to the DBM;\n(b) Undergo a management audit in cooperation with the CHED; and\n(c) Accordingly set up its organizational, administrative, and academic structure, including the appointment of the key officials of the University."}},{"id":"PH-H9533-A20","no":20,"noLabel":{"en":"Section 20."},"heading":{"en":"Appropriations. – The amount necessary to carry out the provisions of this Act shall be charged against the current year"},"text":{"en":"Section 20. Appropriations. – The amount necessary to carry out the provisions of this Act shall be charged against the current year's appropriations of the SSC. Thereafter, such sums as may be necessary for the continued operation and maintenance of the University shall be included in the annual General Appropriations Act."}},{"id":"PH-H9533-A21","no":21,"noLabel":{"en":"Section 21."},"heading":{"en":"Annual Report. - On or before the fifteenth (15th) day of the second month after opening of the regular classes each yea"},"text":{"en":"Section 21. Annual Report. - On or before the fifteenth (15th) day of the second month after opening of the regular classes each year, the Board shall file with the Office of the President of the Philippines and both Houses of Congress, through the CHED Chairperson, a detailed report on the progress, conditions and needs of the University."}},{"id":"PH-H9533-A22","no":22,"noLabel":{"en":"Section 22."},"heading":{"en":"Compliance with CHED Requirements. - The provisions of this Act notwithstanding, the conversion of the institution into"},"text":{"en":"Section 22. Compliance with CHED Requirements. - The provisions of this Act notwithstanding, the conversion of the institution into a state university shall become effective only upon the determination and declaration by the CHED, based on the recommendation of a panel of experts it shall constitute for the purpose, that the institution has complied with the requirements for a university status based on CHED Memorandum Order No. 46, series of 2012.\nThe institution shall retain its status prior to the effectivity of this Act until it is able to comply with the requirements provided herein."}},{"id":"PH-H9533-A23","no":23,"noLabel":{"en":"Section 23."},"heading":{"en":"Supplementary Application. - The provisions of Republic Act No. 8292, otherwise known as the \"Higher Education Moderniza"},"text":{"en":"Section 23. Supplementary Application. - The provisions of Republic Act No. 8292, otherwise known as the \"Higher Education Modernization Act of 1997,\" shall be an integral part of this Act and shall serve as part of the Governing Charter of the University."}},{"id":"PH-H9533-A24","no":24,"noLabel":{"en":"Section 24."},"heading":{"en":"Parity Clause. - All other powers, functions and privileges, responsibilities and limitations to state universities and"},"text":{"en":"Section 24. Parity Clause. - All other powers, functions and privileges, responsibilities and limitations to state universities and their officials under existing laws shall be deemed granted to or imposed upon the University or its officials, whenever appropriate."}},{"id":"PH-H9533-A25","no":25,"noLabel":{"en":"Section 25."},"heading":{"en":"Implementing Rules and Regulations. - Within sixty (60) days from the effectivity of this Act, the Board, in consultatio"},"text":{"en":"Section 25. Implementing Rules and Regulations. - Within sixty (60) days from the effectivity of this Act, the Board, in consultation with the CHED, shall formulate the rules and regulations to fully implement the provisions of this Act."}},{"id":"PH-H9533-A26","no":26,"noLabel":{"en":"Section 26."},"heading":{"en":"Separability Clause. - If, for any reason, any part or provision of this Act is declared invalid or unconstitutional, th"},"text":{"en":"Section 26. Separability Clause. - If, for any reason, any part or provision of this Act is declared invalid or unconstitutional, the remaining parts or provisions not affected thereby shall remain in full force and effect. Section 27. Repealing Clause. - All laws, presidential decrees, executive orders, rules and regulations contrary to or inconsistent with the provisions of this Act are hereby repealed or modified accordingly. Section 28. Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation.\nApproved,\nVICENTE C. SOTTO III\nPresident of the Senate\nGLORIA MACAPAGAL-ARROYO\nSpeaker of the House of Representatives\nThis Act which originated in the House of Representatives was passed by the House of Representatives and the Senate on August 7, 2018 and August 8, 2018, respectively.\nMYRA MARIE D. VILLARICA\nSecretary of the Senate\nDANTE ROBERTO P. MALING\nActing Secretary General\nHouse of Representatives\nApproved: October 11, 2018\n(Sgd.) RODRIGO ROA DUTERTE\nPresident of the Philippines"}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Sorsogon State College in the Province of Sorsogon Into a State University to Be Known as the Sorsogon State University and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"},"recrawled":"2026-10-24 从 https://lawphil.net/statutes/repacts/ra2018/ra_11088_2018.html 重抓，26 → 26 条"};
  FT["PH-H9534"] = {"id":"PH-H9534","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11089_2018.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"授予 Streamtech Systems Technologies Inc. 在菲律宾全境范围内建设、安装、设立、运营和维护各类电信系统的特许经营权法案","en":"An Act Granting Streamtech Systems Technologies Inc. a Franchise to Construct, Install, Establish, Operate, and Maintain Telecommunications Systems Throughout the Philippines","orig":"An Act Granting Streamtech Systems Technologies Inc. a Franchise to Construct, Install, Establish, Operate, and Maintain Telecommunications Systems Throughout the Philippines"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 11089","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-18","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11089_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9534-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Streamtech Systems Technologies Inc., hereunder referred to as the grantee, its successors or assignees, a franchise to construct, install, establish, operate, and maintain for commercial purposes and in the public interest, an international gateway facility to serve and connect the Philippines to other countries and territories, wire and / or wireless telecommunications systems, international and national broadband system, mobile and cellular, including, but not limited to, fiber optics, multichannel multipoint distribution systems, switches, and their value-added services such as transmission of voice, data, facsimile, control signs, audio and video, information services and all other value-added technologies as are available or will be made available through technological advances or innovations in the future; and / or construct, acquire, lease and operate, or manage transmitting and receiving stations, lines, cables, or systems as is or are convenient or essential to efficiently carry out the purpose of this franchise."}},{"id":"PH-H9534-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and / or the availability thereof."}},{"id":"PH-H9534-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"A uthority of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission (NTC) a Certificate of Public Convenience and Necessity and the appropriate permits and licenses for the construction, installation, and operation of its telecommunications systems/facilities. In issuing the certificate, the NTC shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications systems. The NTC shall also have the authority to regulate the construction and operation of the grantee's telecommunications systems. The grantee shall not use any frequency in the radio spectrum without authorization from the NTC. Such certificate shall state the areas covered and the date the grantee shall commence the service. The NTC, however, shall not unreasonably withhold or delay the grant of such authority, permit, or license."}},{"id":"PH-H9534-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoratio n W orks. - For the purpose of erecting and maintaining poles or other supports for said wires or other conductors for the purpose of laying and maintaining underground wires, cables, or other conductors, the grantee, its successors or assignees, shall be authorized to make excavations or lay conduits in any of the public places, roads, highways, streets, lanes, alleys, avenues, sidewalks, or bridges of the province, cities and/or municipalities, with the prior approval of the Department of Public Works and Highways (DPWH) and the local government unit (LGU) concerned, as may be appropriate : Provided, however, That a public place, road, highway, street, lane, alley, avenue, sidewalk, or bridge disturbed, altered or changed by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner by the said grantee, its successors or assignees, in accordance with the standards set by the DPWH or the LGU concerned. Should the grantee, its successors or assignees, after the ten (10)-day notice from the said authority, fail, refuse, or neglect to repair or replace any part of public place, road, highway, street, lane, alley, avenue, sidewalk, or bridge disturbed, altered or changed by the said grantee, its successors or assignees, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition and charge the grantee, its successors or assignees, at double the amount of the costs and expenses for such repair or replacement."}},{"id":"PH-H9534-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. – The grantee shall conform to the ethics of honest enterprise and not use its stations or facilities for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals, and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve, or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology.\nThe grantee shall improve and extend its services in areas not served, and in hazard- and typhoon-prone areas that shall be determined by the National Disaster Risk Reduction and Management Council in coordination with the NTC.\nThe grantee shall also improve and upgrade its equipment, facilities and services, in order to ensure effective compliance with the objectives of Republic Act No. 10639 or \"The Free Mobile Disaster Alerts Act\"."}},{"id":"PH-H9534-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. - The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the NTC or its legal successor."}},{"id":"PH-H9534-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of the Government. - The radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process.\nA special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take over and operate the stations, transmitters, facilities, or equipment of the grantee; to temporarily suspend the operation of any station, transmitter, facility, or equipment in the interest of public safety, security, and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations, transmitters, facilities, or equipment during the period when these shall be so operated."}},{"id":"PH-H9534-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the date of the effectivity of this Act, unless sooner cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\n(a) Commence operations within one (1) year from the approval of its operating permit by the NTC;\n(b) Commence operations within three (3) years from the effectivity of this Act; and\n(c) Operate continuously for two (2) years."}},{"id":"PH-H9534-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Commitment to Provide and Promote the Creation of Employment Opportunities. – The grantee shall create employment opportunities and shall allow on-the-job trainings in their franchise operation: Provided, That priority shall be accorded to the residents in areas where any of its offices is located: Provided, further, That the grantee shall follow the applicable labor standards and allowance entitlement under existing labor laws, rules and regulations and similar issuance s: Provided, finally, That the employment opportunities or jobs created shall be reflected in the General Information Sheet (GIS) to be submitted to the Securities and Exchange Commission annually."}},{"id":"PH-H9534-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Tax Provisions. – The grantee, its successors or assignees, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or thereafter may be required by law to pay, except radio telecommunications and electronic communications equipment, machinery, and spare parts needed in connection with the business of the grantee which shall be exempt from customs duties, tariffs and other taxes, as well as those declared exempt in this section. In addition thereto, the grantee, its successors or assignees, shall pay a value-added tax on all gross receipts of the business transacted under this franchise by the grantee, its successors or assignees, in the Philippines in lieu of any and all taxes of any kind, nature, or description levied, established, or collected by an authority whatsoever including, but not limited to, city, municipal, provincial, or national, from which the grantee is hereby expressly exempted effective from the date of the effectivity of this Act: Provided, That the grantee, its successors or assignees, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H9534-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Bond. - The grantee shall file a bond with the NTC, in the amount that the NTC shall determine, to guarantee compliance with and fulfillment of the conditions under which this franchise is granted. If, after three (3) years from the date of the approval of its permit by the NTC, the grantee shall have fulfilled the same, the bond shall be released by the NTC. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H9534-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Right of Interconnection. - The grantee is hereby authorized to connect or demand connection of its telecommunications systems to other telecommunications systems installed, operated, and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public, under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to review and modification of the NTC."}},{"id":"PH-H9534-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"W arranty in Favor of the National and Local Governments. – The grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, liabilities, demands, or actions arising out of accidents causing injury to persons or damage to property, during the construction or operation of the stations, transmitters, facilities, or equipment of the grantee."}},{"id":"PH-H9534-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"M obile Number Portability. – The grantee shall provide mobile number portability (MNP). It shall set up a mechanism for the purpose of implementing MNP. It shall interconnect directly or indirectly with the infrastructure, facilities, systems, or equipment of other telecommunications franchise grantees. It shall not install network features, functions or capabilities that will impede the implementation of a nationwide MNP system. The NTC shall issue rules and regulations for this purpose, the effectivity of which shall commence upon applicability with other telecommunications franchise grantees."}},{"id":"PH-H9534-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"S ale, Lease, Transfer, Grant of Usufruct, or Assignment of Franchise. – The grantee shall not sell, lease, transfer, grant the usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall transfer the controlling interest of the grantee, whether as a whole or in part, and whether simultaneously or contemporaneously, to any person, firm, company, corporation, or entity without the prior approval of the Congress of the Philippines and compliance with legal requirements stipulated in other statute s: Provided, That any person or entity to which this franchise is sold, transferred, or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H9534-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations : Provided, That in cases where public offer of shares is not applicable, the grantee shall apply other methods of encouraging public participation by citizens and corporations operating public utilities as allowed by law. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9534-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of its franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9534-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Fine. – Failure of the grantee to submit the requisite annual report to Congress shall be penalized with a fine in the amount of One million pesos (P1,000,000.00) per working day of noncompliance, the effectivity of which shall commence upon applicability with other telecommunications franchise grantees: Provided, That in the interim, the grantee shall be liable to pay the fine of Five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee separate from the reportorial penalties imposed by the NTC and the same shall be remitted to the National Treasury."}},{"id":"PH-H9534-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted upon prior review and approval of Congress, shall ipso facto become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, That the foregoing shall neither apply to nor affect the provisions of telecommunications franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise."}},{"id":"PH-H9534-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H9534-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"S eparability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9534-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Repealing Clause. - All laws, decrees, executive orders, rules and regulations, or any part or provision thereof which are not consistent with this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H9534-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in th e Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Streamtech Systems Technologies Inc. a Franchise to Construct, Install, Establish, Operate, and Maintain Telecommunications Systems Throughout the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9535"] = {"id":"PH-H9535","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11090_2018.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛省 Igbaras 市镇 Alameda 描笼涯的 Igbaras 国立中学附属校分离，改设为独立的 Alameda 国立中学，并为此拨款","en":"An Act Separating the Igbaras National High School - Alameda Extension in Barangay Alameda, Municipality of Igbaras, Province of Iloilo From the Igbaras National High School, Converting It Into an Independent National High School to Be Known as Alameda National High School and Appropriating Funds Therefor","orig":"An Act Separating the Igbaras National High School - Alameda Extension in Barangay Alameda, Municipality of Igbaras, Province of Iloilo From the Igbaras National High School, Converting It Into an Independent National High School to Be Known as Alameda National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 11090","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11090_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9535-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Igbaras National High School —Alameda Extension in Barangay Alameda, Municipality of Igbaras, Province of Iloilo is hereby separated from the Igbaras National High School and converted into an independent national high school to be known as Alameda National High School."}},{"id":"PH-H9535-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities, and records of the Igbaras National High School - Alameda Extension are hereby transferred to and absorbed by the Alameda National High School."}},{"id":"PH-H9535-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationalization of the Alameda National High School, the initial funding of which shall be charged against the current year's appropriation of the Igbaras National High School - Alameda Extension. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H9535-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education shall formulate the rules and regulations necessary to carry out the purpose of this Act within one hundred twenty (120) days after its effectivity."}},{"id":"PH-H9535-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p135","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Igbaras National High School - Alameda Extension in Barangay Alameda, Municipality of Igbaras, Province of Iloilo From the Igbaras National High School, Converting It Into an Independent National High School to Be Known as Alameda National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
